	('lucy', 'foxnews', 'sh', 2, '32d07b5a-0415-11e7-b133-7831c1d422a2', '', '', 'richard/news/foxnews.sh', '', '', '', '', 0, 'kwk r rss.rb "http://feeds.foxnews.com/foxnews/latest?format=xml"', '', '', 1, 1489569830000, 0, 0, 0, '1ab0e61d1c443ec5eb614d02198472b78ff84beb1530fb6c9e1307fe070ff0c4', '', true, false, '', true, 'cass', false, 0, 1488987537723, 1495404784613, 0, e'============== \x1b[36mFOXNews.com\x1b[0m =========\x1b[0m'),
	('lucy', 'rss', 'rb', 2, '4197733d-0415-11e7-b134-7831c1d422a2', '', '', 'richard/feeds/rss.rb', '', '', '', '', 0, e'require \'rss\'\nrequire \'cgi\'\n\nclass String\n  def col(color_code)\n    "\\e[#{color_code}m#{self}\\e[0m"\n  end\nend\n\nrss = RSS::Parser.parse(ARGV[0], false)\nmargin = "  "\n\ncase rss.feed_type\n  when \'rss\'\n    puts "\\n\\n"\n    puts margin + "============== " + rss.channel.title.col(36) + " =============="\n    puts "\\n"\n    puts margin + rss.channel.description.col(2)\n    puts "\\n"\n    \n    rss.items.take(5).each{ |item|\n\titem.title.sub! \'&lsquo;\', \'"\'\n\titem.title.sub! \'&rsquo;\', \'"\'\n\tputs margin + item.title\n\tif (item.pubDate) then\n        \tputs margin + item.pubDate.strftime("%I:%M%P %d %B").col(2)\n\tend\n        puts margin + item.link.col(2)\n        puts "\\n"\n    }\n    \n  when \'atom\'\n    puts "\\n\\n"\n    puts margin + "============== " + rss.title.content.col(36) + " =============="\n    puts "\\n"\n    if (rss.subtitle) then\n        puts margin\n    end\n    puts "\\n"\n    rss.items.take(5).each { | e | \n        puts margin + e.title.content\n        puts margin + e.updated.content.strftime("%I:%M%P %d %B").col(2)\n        puts margin + e.link.href.col(2)\n        puts "\\n"\n    }\nend\nputs "\\n"', '', '', 1, 1489569830000, 0, 0, 0, '0f6d97d2435a50255be14077766a53d2805709ac955dfa8ce4c7fdb6d906da23', '', true, false, '', true, 'cass', false, 0, 1488987518918, 1495404784635, 0, e'============== \x1b[36mFOXNews.com\x1b[0m =========\x1b[0m'),
