	('richard', 'basic-cli', 'py', 3, '95572087-0dac-11e7-8e5a-7831c1d422a2', '', '', '', '', '', 'ansi', 'c15ef710-0765-11e7-845b-7831c1d422a2', 0, e'import sys, tty\n \ndef command_line():\n    tty.setraw(sys.stdin)\n    while True: # loop for each line\n    # Define data-model for an input-string with a cursor\n        input = ""\n        while True: # loop for each character\n            char = ord(sys.stdin.read(1)) # read one char and get char code\n            \n            # Manage internal data-model\n            if char == 3: # CTRL-C\n                return\n            elif 32 <= char <= 126:\n                input = input + chr(char)\n            elif char in {10, 13}:\n                sys.stdout.write(u"\\u001b[1000D")\n                print "\\nechoing... ", input\n                input = ""\n\n            # Print current input-string\n            sys.stdout.write(u"\\u001b[1000D")  # Move all the way left\n            sys.stdout.write(input)\n            sys.stdout.flush()\n\ncommand_line();', '', '', 1, 1491440619000, 0, 0, 0, '842a95796c2a8371bd999fc92737949b2f6d408e10358ac2c4a5d95f60b30d26', '', true, false, '', true, 'cass', false, 0, 1490042088141, 1495404777079, 0, ''),
	('richard', 'chars', 'sh', 11, 'cc9afef2-0765-11e7-845c-7831c1d422a2', '', '', '', '', 'lists ascii chars with respective code point integers', 'ansi', 'c15ef710-0765-11e7-845b-7831c1d422a2', 0, e'echo -e "\\n"\nawk \'BEGIN{for(i=32;i<128;i++)printf "%c \\033[2m%s\\033[0m  ",i, i}\';echo\necho -e "\\n"', '', '', 1, 1497228770827, 0, 5, 0, '32e4d572631266d0b0ac31540d20c2a8fed64b56dfcdc0f9f068a7551b1dea5b', '', true, false, '', true, 'cass', false, 0, 1489524160770, 1495404777884, 1497228770827, e'\x1b[2m32\x1b[0m  ! \x1b[2m33\x1b[0m  " \x1b[2m34\x1b[0m  # \x1b[2\x1b[0m'),
	('richard', 'color-table', 'sh', 4, 'd78a5752-0768-11e7-845f-7831c1d422a2', '', '', '', '', '', 'ansi', 'c15ef710-0765-11e7-845b-7831c1d422a2', 0, e' for a in 0 1 4 5 7; do\n              echo "a=$a " \n              for (( f=0; f<=9; f++ )) ; do\n                      for (( b=0; b<=9; b++ )) ; do\n                              #echo -ne "f=$f b=$b" \n                              echo -ne "\\\\033[${a};3${f};4${b}m"\n                              echo -ne "\\\\\\\\\\\\\\\\033[${a};3${f};4${b}m"\n                              echo -ne "\\\\033[0m "\n                      done\n              echo\n              done\n              echo\n      done\n      echo', '', '', 1, 1490043346000, 0, 0, 0, 'beba0d0ead15bfae34b8d5ac3abb19e2d48e7ff1131f4b37de97fbe796f2bbc0', '', true, false, '', true, 'cass', false, 0, 1490043377828, 1495404777026, 0, e'a=0   \x1b[0;30;40m\\\\033[0;30;40m\x1b[0m \x1b[0;30;41m\x1b[0m'),
	('richard', 'colors256', 'sh', 28, '841a93e0-ccb5-11e6-8e2a-27249dd1b81b', '', '', '', '', '', 'ansi', 'c15ef710-0765-11e7-845b-7831c1d422a2', 0, e'echo -e ""\nfor C in {0..255}; do  \n    printf "\\033[48;5;${C}m   ${C}   \\033[0;00m  "\n    if [[ "$C" -eq 15 ]]; then\n\techo -e "\\n"\n    fi\n    remainder="$((($C -15)%6))"\n    if [[ "$C" -gt 15 ]] && [[ "$remainder" -eq 0 ]]; then\n      echo -e "\\n"\n    fi  \ndone\necho -e "\\n"', '', e'\n\t\n\x05color\x10\x01\n\n\n\x06colour\x10\x01\n\n\n\x06system\x10\x01', 1, 1502832273537, 0, 11, 0, '62c47f0822d40b4d18dccf5b618cd305186cc8371171c19b62c358425402a2b9', '', true, false, '', true, 'cass', false, 0, 1490041194177, 1495404777239, 1502832273537, e'\x1b[48;5;0m   0   \x1b[0;00m  \x1b[48;5;1m   1   \x1b[0;\x1b[0m'),
	('richard', 'colors8', 'sh', 23, 'd3d509f5-0dce-11e7-a65a-7831c1d422a2', '', '', 'richard/colors256', '', '', 'ansi', 'c15ef710-0765-11e7-845b-7831c1d422a2', 0, e'margin="   "\n\necho -e "\\n\\n${margin}Foreground:\\n${margin}"\nfor C in {30..39}; do  \n    printf "\\033[${C}m  ${C}  \\033[0m  "\ndone\necho -e "\\n\\n${margin}Background:\\n${margin}"\nfor C in {40..49}; do  \n    printf "\\033[${C}m  ${C}  \\033[0m  "\ndone\necho -e "\\n\\n${margin}Attributes:\\n${margin}"\nfor C in {0..8}; do  \n    printf "\\033[${C}m  ${C}  \\033[0m  "\ndone\necho -e "\\n"\necho -e "${margin}Notes:\\n"\necho -e "${margin}- 30 = black text"\nprintf  "${margin}- \\\\\\\\033[{n}m  starts the sequence.\\n"\nprintf  "${margin}- \\\\\\\\033[0m ends the sequence.\\n"\necho -e "\\n"', '', e'\n\t\n\x05color\x10\x01\n\n\n\x06colour\x10\x01\n\n\n\x06system\x10\x01', 1, 1502832268213, 0, 3, 0, 'b49e0fbca72c1b5c2f1ae1ddd0c8341c502448d9c25487d70e6104708bca971e', '', true, false, '', true, 'cass', false, 0, 1490058188599, 1495404776933, 1502832268213, e'Foreground:       \x1b[30m  30  \x1b[0m  \x1b[31m  31\x1b[0m'),
	('richard', 'cursor', 'txt', 14, '324800c4-0dae-11e7-8e5b-7831c1d422a2', '', '', '', '', '', 'ansi', 'c15ef710-0765-11e7-845b-7831c1d422a2', 0, e'Up: esc[{n}A moves cursor up by n\n\nDown: esc[{n}B moves cursor down by n\n\nRight: esc[{n}C moves cursor right by n\n\nLeft: esc[{n}D moves cursor left by n\n\nNext Line: esc[{n}E moves cursor to beginning of line n lines down\n\nPrev Line: esc[{n}F moves cursor to beginning of line n lines up\n\nSet Column: esc[{n}G moves cursor to column n\n\nSet Position: esc[{n};{m}H moves cursor to row n column m\n\nClear Screen: esc[{n}J\nn=0 clears from cursor until end of screen,\nn=1 clears from cursor to beginning of screen\nn=2 clears entire screen\n\nClear Line: esc[{n}K clears the current line\nn=0 clears from cursor to end of line\nn=1 clears from cursor to start of line\nn=2 clears entire line\n\nSave Position: esc[s saves the current cursor position\nSave Position: esc[u restores the cursor to the last saved position\nReport Position: esc[6n\n\nScroll up esc]{n}S\nScroll down esc]{n}T\n\nHide cursor: tput civis  esc[?25l\nShow cursor: tput cnorm  esc[?25h', '', '', 0, 1491513352000, 0, 0, 0, '93872af5592244fbb0c585ec962ce91806fab6c56aafcc6e3869ce67a67851fb', '', true, false, '', true, 'cass', false, 0, 1491436705972, 1495404773159, 0, ''),
	('richard', 'decorations', 'py', 2, 'b96dab1c-0daa-11e7-8e55-7831c1d422a2', '', '', '', '', '', 'ansi', 'c15ef710-0765-11e7-845b-7831c1d422a2', 0, e'print u"\\u001b[1m BOLD \\u001b[0m\\u001b[4m Underline \\u001b[0m\\u001b[7m Reversed \\u001b[0m"', '', '', 1, 1492032443000, 0, 0, 0, 'c085438c9445728175cb96d7185877e05093780544f90d5484e0c1c102334cf3', '', true, false, '', true, 'cass', false, 0, 1490041258681, 1495404777224, 0, e'\x1b[1m BOLD \x1b[4m Underline \x1b[7m Reversed \x1b[0m\x1b[0m'),
	('richard', 'escape-seq', 'url', 1, '09dec41d-19d2-11e7-b24a-7831c1d422a2', '', '', '', '', '', 'ansi', 'c15ef710-0765-11e7-845b-7831c1d422a2', 0, 'http://ascii-table.com/ansi-escape-sequences.php', '', '', 1, 1491430766000, 0, 0, 0, 'acde9b8a2be153dbbefa69b592eca52a403c5cd1df1cec2e6e3697898bc9e4a1', '', true, false, '', true, 'cass', false, 0, 1491377555751, 1495404773374, 0, e'\x1b[0m'),
	('richard', 'escape-tut', 'url', 2, '6dc87ca1-0dab-11e7-8e57-7831c1d422a2', '', '', '', '', '', 'ansi', 'c15ef710-0765-11e7-845b-7831c1d422a2', 0, 'http://www.lihaoyi.com/post/BuildyourownCommandLinewithANSIescapecodes.html', '', '', 0, 0, 0, 0, 0, '87653d2605781669721120d8bb2506813493d7721a598fcf84a2c2a0ab576ca4', '', true, false, '', true, 'cass', false, 0, 1490041580094, 1495404777159, 0, 'coming soon'),
	('richard', 'full_cli', 'py', 2, 'bfd672b5-0dae-11e7-8e5c-7831c1d422a2', '', '', '', '', '', 'ansi', 'c15ef710-0765-11e7-845b-7831c1d422a2', 0, e'import sys, tty\ndef syntax_highlight(input):\n    stripped = input.rstrip()\n    return stripped + u"\\u001b[41m" + " " *  (len(input) - len(stripped)) + u"\\u001b[0m"\n\ndef command_line():\n    tty.setraw(sys.stdin)\n    while True: # loop for each line\n        # Define data-model for an input-string with a cursor\n        input = ""\n        index = 0\n        while True: # loop for each character\n            char = ord(sys.stdin.read(1)) # read one char and get char code\n            \n            # Manage internal data-model\n            if char == 3: # CTRL-C\n                return\n            elif 32 <= char <= 126:\n                input = input[:index] + chr(char) + input[index:]\n                index += 1\n            elif char in {10, 13}:\n                sys.stdout.write(u"\\u001b[1000D")\n                print "\\nechoing... ", input\n                input = ""\n                index = 0\n            elif char == 27:\n                next1, next2 = ord(sys.stdin.read(1)), ord(sys.stdin.read(1))\n                if next1 == 91:\n                    if next2 == 68: # Left\n                        index = max(0, index - 1)\n                    elif next2 == 67: # Right\n                        index = min(len(input), index + 1)\n            elif char == 127:\n                input = input[:index-1] + input[index:]\n                index -= 1\n            # Print current input-string\n            sys.stdout.write(u"\\u001b[1000D")\n            sys.stdout.write(u"\\u001b[0K")\n            sys.stdout.write(syntax_highlight(input))\n            sys.stdout.write(u"\\u001b[1000D")\n            if index > 0:\n                sys.stdout.write(u"\\u001b[" + str(index) + "C")\n            sys.stdout.flush()\n\ncommand_line()', '', '', 1, 1490043029000, 0, 0, 0, '6c49e7217db6086e5ac2e4297d8b002e577ec919f37ab1d7a08e143f98f9549d', '', true, false, '', true, 'cass', false, 0, 1490042998463, 1495404777044, 0, e'\x1b[1000D\x1b[0Kp\x1b[41m\x1b[0m\x1b[1000D\x1b[1C\x1b[1000D\x1b[0Kpr\x1b[0m'),
	('richard', 'go-red', 'py', 6, '03457c0b-0daa-11e7-8e53-7831c1d422a2', '', '', '', '', '', 'ansi', 'c15ef710-0765-11e7-845b-7831c1d422a2', 0, e'print u"\\u001b[31m"', '', '', 1, 1490044046000, 0, 0, 0, 'f1ef0e0f95bb1506352818cd5d8918f41c3746575f530af910770758339e48b6', '', true, false, '', true, 'cass', false, 0, 1490044062945, 1495404776989, 0, e'\x1b[0031m\x1b[0m'),
	('richard', 'loading', 'py', 2, '11699be4-0dab-11e7-8e56-7831c1d422a2', '', '', '', '', '', 'ansi', 'c15ef710-0765-11e7-845b-7831c1d422a2', 0, e'import time, sys\ndef loading():\n    print "Loading..."\n    for i in range(0, 100):\n        time.sleep(0.1)\n        sys.stdout.write(u"\\u001b[1000D" + str(i + 1) + "%")\n        sys.stdout.flush()\n    print\n    \nloading()', '', '', 1, 1492032148000, 0, 0, 0, 'aef22ef7575f8f389535cce1e93f9f250d99000665ec98558a8d13aa50a904a7', '', true, false, '', true, 'cass', false, 0, 1490041406456, 1495404777196, 0, e'12%ding...\x1b[0m'),
	('richard', 'multi-progress-bars', 'py', 3, 'e2abba49-0dab-11e7-8e59-7831c1d422a2', '', '', '', '', '', 'ansi', 'c15ef710-0765-11e7-845b-7831c1d422a2', 0, e'import time, sys, random\ndef loading(count):\n    all_progress = [0] * count\n    sys.stdout.write("\\n" * count) # Make sure we have space to draw the bars\n    while any(x < 100 for x in all_progress):\n        time.sleep(0.01)\n        # Randomly increment one of our progress values\n        unfinished = [(i, v) for (i, v) in enumerate(all_progress) if v < 100]\n        index, _ = random.choice(unfinished)\n        all_progress[index] += 1\n        \n        # Draw the progress bars\n        sys.stdout.write(u"\\u001b[1000D") # Move left\n        sys.stdout.write(u"\\u001b[" + str(count) + "A") # Move up\n        for progress in all_progress: \n            width = progress / 4\n            print "[" + "#" * width + " " * (25 - width) + "]"\n        \nloading(5)', '', '', 1, 1490041918000, 0, 0, 0, 'c4a40a1f0ec2c8d50cc91cc2f8e88a349eb4a14c98c07539648f731592bd699b', '', true, false, '', true, 'cass', false, 0, 1490041911107, 1495404777107, 0, e'\x1b[1000D\x1b[5A[                         ]  [\x1b[0m'),
	('richard', 'progress-bar', 'py', 2, 'aaddd11e-0dab-11e7-8e58-7831c1d422a2', '', '', '', '', '', 'ansi', 'c15ef710-0765-11e7-845b-7831c1d422a2', 0, e'import time, sys\ndef loading():\n    print "Loading..."\n    for i in range(0, 100):\n        time.sleep(0.1)\n        width = (i + 1) / 4\n        bar = "[" + "#" * width + " " * (25 - width) + "]"\n        sys.stdout.write(u"\\u001b[1000D" +  bar)\n        sys.stdout.flush()\n    print\n    \nloading()', '', '', 1, 1492032874000, 0, 0, 0, 'bc2c4f4d8f49458ac1445665f2086490d271c69ffe1b05e9750fc51590efca89', '', true, false, '', true, 'cass', false, 0, 1490041663930, 1495404777126, 0, ''),
	('richard', 'reset', 'py', 3, '1ceaf49f-0daa-11e7-8e54-7831c1d422a2', '', '', '', '', '', 'ansi', 'c15ef710-0765-11e7-845b-7831c1d422a2', 0, e'print u"\\u001b[0m"', '', '', 1, 1497211906393, 0, 2, 0, '3d46acc8f27fc098f4073828ecbcfb976cb4c1c4eddea9394485e54def21300e', '', true, false, '', true, 'cass', false, 0, 1490041008577, 1495404777268, 1497211906393, e'\x1b[0m  \x1b[0m\x1b[0m'),
	('richard', 'screen-size-watch', 'sh', 4, '6c29bb53-1a55-11e7-b24c-7831c1d422a2', '', '', '', '', '', 'ansi', 'c15ef710-0765-11e7-845b-7831c1d422a2', 0, e'   #!/bin/bash\n    # term_size3 - Dynamically display terminal window size\n    #              with text centering\n\n    redraw() {\n        local str width height length\n        \n        width=$(tput cols)\n        height=$(tput lines)\n        str="Width = $width Height = $height"\n        length=${#str}\n        clear\n        tput cup $((height / 2)) $(((width / 2) - (length / 2)))\n        echo "$str"\n    }\n\n    trap redraw WINCH\n\n    redraw\n    while true; do\n        :\n    done', '', '', 0, 1491434371000, 0, 0, 0, '7afeb0d5c3c15dc008ed3eb25bfee3489cd36f098f52059f7258dd85ff0f135a', '', true, false, '', true, 'cass', false, 0, 1491434379200, 1495404773303, 0, ''),
	('richard', 'term-info', 'sh', 4, 'a805be14-1a58-11e7-b250-7831c1d422a2', '', '', '', '', '', 'ansi', 'c15ef710-0765-11e7-845b-7831c1d422a2', 0, e'infocmp\n\necho -e "\\nNOTE: type \'man terminfo\' for descriptions of capabilities" ', '', '', 1, 1491437518000, 0, 0, 0, 'c8f7ae56ae7fdc4cf0116747997f58c2db57ee3b0fbce5e46e0824a9d9d54ea9', '', true, false, '', true, 'cass', false, 0, 1491435649719, 1495404773200, 0, e'#Reconstructed via infocmp from file: /lib/te\x1b[0m'),
	('richard', 'terminal-type', 'sh', 2, '4665f492-1a54-11e7-b24b-7831c1d422a2', '', '', '', '', '', 'ansi', 'c15ef710-0765-11e7-845b-7831c1d422a2', 0, 'echo $TERM', '', '', 1, 1497211985435, 0, 1, 0, '4544d370e4293bb034f9bf507ca4f7c806d3fc340e2962fcfe2354eafca81a37', '', true, false, '', true, 'cass', false, 0, 1491433496800, 1495404773328, 1497211985435, e'xterm-256color\x1b[0m'),
	('richard', 'time-bar', 'py', 60, '51a8a15b-1fc6-11e7-a2af-7831c1d422a2', '', '', 'richard/progress-bar', '', '', 'ansi', 'c15ef710-0765-11e7-845b-7831c1d422a2', 0, e'import time, sys\n\ndef loading():\n    timeout=float(sys.argv[1])\n    micros=int(timeout*10)\n    maxwidth=70\n    \n    for i in range(0, micros):\n        time.sleep(0.1)\n        progress=maxwidth*(micros-i)/micros\n        remaining=maxwidth-progress\n        bar = "|" + ("*" * progress) + (" " * remaining) + "| " + str(timeout-0.1-(float(i)/10.0)) + "s"\n        sys.stdout.write(u"\\u001b[1000D" +  bar + u"\\u001b[?25l")\n        sys.stdout.flush()\n    \nloading()\nsys.stdout.write(u"\\u001b[1K")\nsys.stdout.write(u"\\u001b[1000D")\nsys.stdout.write( "*** Ignition... ***\\n")\nsys.stdout.write(u"\\u001b[?25h")\nsys.stdout.flush()', '', '', 2, 1497339259411, 0, 18, 0, 'a130d04292f05f400fe342f821f5f90c0a6b23360dd324936ee2038d700745a6', '', true, false, '', true, 'cass', false, 0, 1492400710188, 1495404772024, 1497339259411, e'Traceback (most recent call last):    File "<\x1b[0m'),
	('richard', 'tput-colors', 'sh', 2, 'd6a56498-1a56-11e7-b24e-7831c1d422a2', '', '', '', '', '', 'ansi', 'c15ef710-0765-11e7-845b-7831c1d422a2', 0, e' #!/bin/bash\n\n    # tput_colors - Demonstrate color combinations.\n\n    for fg_color in {0..7}; do\n        set_foreground=$(tput setaf $fg_color)\n        for bg_color in {0..7}; do\n            set_background=$(tput setab $bg_color)\n            echo -n $set_background$set_foreground\n            printf \' F:%s B:%s \' $fg_color $bg_color\n        done\n        echo $(tput sgr0)\n    done', '', '', 1, 1491434601000, 0, 0, 0, '830a63b67302f15ecb1a63d864cd46221614929e9f6aecf93028251235d1e42b', '', true, false, '', true, 'cass', false, 0, 1491434595884, 1495404773286, 0, e'\x1b[30m F:0 B:0 \x1b[30m F:0 B:1 \x1b[30m F:0 B:2 \x1b[3\x1b[0m'),
	('richard', 'tput-menu', 'sh', 3, '0012044a-1a57-11e7-b24f-7831c1d422a2', '', '', '', '', '', 'ansi', 'c15ef710-0765-11e7-845b-7831c1d422a2', 0, e' #!/bin/bash\n\n    # tput_menu: a menu driven system information program\n\n    BG_BLUE="$(tput setab 4)"\n    BG_BLACK="$(tput setab 0)"\n    FG_GREEN="$(tput setaf 2)"\n    FG_WHITE="$(tput setaf 7)"\n\n    # Save screen\n    tput smcup\n\n    # Display menu until selection == 0\n    while [[ $REPLY != 0 ]]; do\n      echo -n ${BG_BLUE}${FG_WHITE}\n      clear\n      cat <<- _EOF_\n        Please Select:\n\n        1. Display Hostname and Uptime\n        2. Display Disk Space\n        3. Display Home Space Utilization\n        0. Quit\n\n    _EOF_\n\n      read -p "Enter selection [0-3] > " selection\n      \n      # Clear area beneath menu\n      tput cup 10 0\n      echo -n ${BG_BLACK}${FG_GREEN}\n      tput ed\n      tput cup 11 0\n\n      # Act on selection\n      case $selection in\n        1)  echo "Hostname: $HOSTNAME"\n            uptime\n            ;;\n        2)  df -h\n            ;;\n        3)  if [[ $(id -u) -eq 0 ]]; then\n              echo "Home Space Utilization (All Users)"\n              du -sh /home/* 2> /dev/null\n            else\n              echo "Home Space Utilization ($USER)"\n              du -s $HOME/* 2> /dev/null | sort -nr\n            fi\n            ;;\n        0)  break\n            ;;\n        *)  echo "Invalid entry."\n            ;;\n      esac\n      printf "\\n\\nPress any key to continue."\n      read -n 1\n    done\n\n    # Restore screen\n    tput rmcup\n    echo "Program terminated."', '', '', 2, 1492033709000, 0, 0, 0, '2f6694acb73e1bf1c75f86fa7e37025ae4aed61100dc523a9b0c4baa26508aaf', '', true, false, '', true, 'cass', false, 0, 1491434688419, 1495404773213, 0, e'kwk constraint: \'/dev/null\' is not allowed in\x1b[0m'),
	('richard', 'tput-ref', 'txt', 4, '9f2c6ed2-1a56-11e7-b24d-7831c1d422a2', '', '', '', '', '', 'ansi', 'c15ef710-0765-11e7-845b-7831c1d422a2', 0, e'CURSOR\n\nsc\tSave the cursor position\nrc\tRestore the cursor position\nhome\tMove the cursor to upper left corner (0,0)\ncup <row> <col>\tMove the cursor to position row, col\ncud1\tMove the cursor down 1 line\ncuu1\tMove the cursor up 1 line\ncivis\tSet to cursor to be invisible\ncnorm\tSet the cursor to its normal state\n\nTEXT EFFECTS\n\nCapname\tDescription\nbold\tStart bold text\nsmul\tStart underlined text\nrmul\tEnd underlined text\nrev\tStart reverse video\nblink\tStart blinking text\ninvis\tStart invisible text\nsmso\tStart "standout" mode\nrmso\tEnd "standout" mode\nsgr0\tTurn off all attributes\nsetaf <value>\tSet foreground color\nsetab <value>\tSet background color\n\nSCREEN\n\nCapname\tDescription\nsmcup\tSave screen contents\nrmcup\tRestore screen contents\nel\tClear from the cursor to the end of the line\nel1\tClear from the cursor to the beginning of the line\ned\tClear from the cursor to the end of the screen\nclear\tClear the entire screen and home the cursor', '', '', 0, 1491434624000, 0, 0, 0, '454dbf810f49151494b8a189dbf262c12e6c2bfb3202cdc44b87e3190c1f0421', '', true, false, '', true, 'cass', false, 0, 1491434637028, 1495404773242, 0, ''),
	('richard', 'breakdown', 'sh', 28, '940da0c6-1b0c-11e7-9c6c-7831c1d422a2', '', '', '', '', '', 'apps', '127661aa-127c-11e7-aa7d-7831c1d422a2', 0, e'list=$(kwk -n enchilada)\n\necho -e "Top Extensions"\necho -e "${list}"| awk \'{print $4}\'  | sort | uniq -c | sort -r | head\necho -e "Bulging Pouches"\necho -e "${list}"| awk \'{print $3}\'  | sort | uniq -c | sort -r | head\necho -e "Slim Pouches"\necho -e "${list}"| awk \'{print $3}\'  | sort | uniq -c | sort | head\necho -e "Run Count"\necho -e "${list}"| sed 1d | sort -rn -k 8 | awk \'{printf  "  %-3s %s.%s\\n", $8, $1, $4}\'  | head\necho -e "Dependencies"\necho -e "${list}"| sed 1d | sort -rn -k 9 |awk \'{printf  "  %-3s %s.%s\\n", $9, $1, $4}\'   | head', '', '', 1, 1491530405000, 0, 0, 0, 'dbb1c77f3d8b3b6e40926054fddcc5df4bf2f794ae527a43d49b7ad1f743540d', '', true, false, '', true, 'cass', false, 0, 1491517192218, 1495404772853, 0, ''),
