	('richard', 'countdown', 'sh', 39, 'cbc89fec-1fc2-11e7-a2ae-7831c1d422a2', '', '', '', e'\n\x1d\n\x07richard\x12\x04ansi\x1a\btime-bar"\x02py', '', 'apps', '127661aa-127c-11e7-aa7d-7831c1d422a2', 0, e'echo "Countdown to launch \'${1}\'"\nkwk run /richard/ansi/time-bar.py ${0}\necho -e "*** Lift off! ***"\n("${1}")\n', '', '', 2, 1497339259471, 0, 13, 0, 'a53aa034074b190181e50c63e8fc79fd394ea0abe591841ab0b28e103cf7c468', '', true, false, '', true, '', false, 0, 1496517783976, 1496517783976, 1497339259471, e'1: line 5: \U0001F680: command not found\x1b[0m'),
