rmation: You may need to update /etc/fstab.\n\nroot@ip-172-31-17-17:/home/ubuntu# blkid xfdv\nroot@ip-172-31-17-17:/home/ubuntu# blkid xvdf\nroot@ip-172-31-17-17:/home/ubuntu# blkid /dev/xvdf\n/dev/xvdf: PTUUID="52d649e3" PTTYPE="dos"\nroot@ip-172-31-17-17:/home/ubuntu# lsblk\nNAME    MAJ:MIN RM SIZE RO TYPE MOUNTPOINT\nxvda    202:0    0   8G  0 disk\n\U00002514\U00002500xvda1 202:1    0   8G  0 part /\nxvdf    202:80   0  30G  0 disk\n\U00002514\U00002500xvdf1 202:81   0  30G  0 part\nroot@ip-172-31-17-17:/home/ubuntu# e2fsck -f /dev/xvdf\ne2fsck 1.42.13 (17-May-2015)\next2fs_open2: Bad magic number in super-block\ne2fsck: Superblock invalid, trying backup blocks...\ne2fsck: Bad magic number in super-block while trying to open /dev/xvdf\n\nThe superblock could not be read or does not describe a valid ext2/ext3/ext4\nfilesystem.  If the device is valid and it really contains an ext2/ext3/ext4\nfilesystem (and not swap or ufs or something else), then the superblock\nis corrupt, and you might try running e2fsck with an alternate superblock:\n    e2fsck -b 8193 <device>\n or\n    e2fsck -b 32768 <device>\n\nroot@ip-172-31-17-17:/home/ubuntu# e2fsck -b 32768 /dev/xvdf\ne2fsck 1.42.13 (17-May-2015)\ne2fsck: Bad magic number in super-block while trying to open /dev/xvdf\n\nThe superblock could not be read or does not describe a valid ext2/ext3/ext4\nfilesystem.  If the device is valid and it really contains an ext2/ext3/ext4\nfilesystem (and not swap or ufs or something else), then the superblock\nis corrupt, and you might try running e2fsck with an alternate superblock:\n    e2fsck -b 8193 <device>\n or\n    e2fsck -b 32768 <device>\n\nroot@ip-172-31-17-17:/home/ubuntu#', '', '', 0, 0, 0, 0, 0, 'cd48d28fb1fa49d8a6a130cac4b4e9542cd15553a51eec0a22044828906f09f7', '', true, false, '', true, '', false, 0, 1498684688704, 1498684688704, 1498684688704, ''),
