	('richard', 'rss', 'rb', 79, 'f06b9dac-03ab-11e7-8646-7831c1d422a2', '', '', '', '', '', 'feeds', '74409dc7-f008-11e6-a9c7-7831c1d422a2', 0, e'require \'rss\'\nrequire \'cgi\'\n\nclass String\n  def col(color_code)\n    "\\e[#{color_code}m#{self}\\e[0m"\n  end\nend\n\nrss = RSS::Parser.parse(ARGV[0], false)\nmargin = "  "\n\ncase rss.feed_type\n  when \'rss\'\n    puts "\\n\\n"\n    puts margin + "============== " + rss.channel.title.col(36) + " =============="\n    puts "\\n"\n    puts margin + rss.channel.description.col(2)\n    puts "\\n"\n    \n    rss.items.take(5).each{ |item|\n\titem.title.sub! \'&lsquo;\', \'"\'\n\titem.title.sub! \'&rsquo;\', \'"\'\n\tputs margin + (" " + item.title + " ").col(7)\n\tif (item.pubDate) then\n        \tputs margin + item.pubDate.strftime("%I:%M%P %d %B").col(2)\n\tend\n        puts margin + item.link.col(2)\n        puts "\\n"\n    }\n    \n  when \'atom\'\n    puts "\\n\\n"\n    puts margin + "============== " + rss.title.content.col(36) + " =============="\n    puts "\\n"\n    if (rss.subtitle) then\n        puts margin\n    end\n    puts "\\n"\n    rss.items.take(5).each { | e | \n        puts margin + e.title.content.col(7);\n        puts margin + e.updated.content.strftime("%I:%M%P %d %B").col(2)\n        puts margin + e.link.href.col(2)\n        puts "\\n"\n    }\nend\nputs "\\n"', '', '', 1, 1502832284260, 0, 19, 0, '5bda9dadee1a674dbf4779da32963ea4cab397d210631192d515105d762653df', '', true, false, '', true, 'cass', false, 0, 1489881950076, 1495404777406, 1502832284260, e'============== \x1b[36mFOXNews.com\x1b[0m =========\x1b[0m'),
	('richard', 'rss', 'sh', 22, '93cb7443-03a2-11e7-83b6-7831c1d422a2', '', '', '', '', '', 'feeds', '74409dc7-f008-11e6-a9c7-7831c1d422a2', 0, e'#!/bin/sh\nxmlgetnext () {\n   local IFS=\'>\'\n   read -d \'<\' TAG VALUE\n}\n\ncounter=0\ncat $1 | while xmlgetnext ; do\n#echo $TAG $VALUE\n   case $TAG in\n      \'item\')\n         title=\'\'\n         link=\'\'\n         pubDate=\'\'\n         description=\'\'\n         ;;\n      \'title\')\n         title= \'<title\' #$(echo "$VALUE" | sed -e \'s/![CDATA[//g\')\n         ;;\n      \'link\')\n         link="$VALUE"\n         ;;\n      \'pubDate\')\n         pubDate="$VALUE"\n         ;;\n      \'description\')\n         # convert \'&lt;\' and \'&gt;\' to \'<\' and \'>\'\n         description=$(echo "$VALUE" | sed -e \'s/&lt;/</g\' -e \'s/&gt;/>/g\')\n         ;;\n      \'/item\')\n           echo -e "== ${title} ==\\n${description} - ${pubDate}\\n$link\\n\\n"\n\t   counter=$((counter+1))\n\t   if [[ "$counter" -gt 5 ]]; then\n\t\texit 0\n \t   fi\n         ;;\n      esac\n\ndone', '', '', 1, 1488942144000, 0, 0, 0, 'a56d299b3d100bd4e2b2d6dd14990f19e753b2e2737c520a4fd645605a667c64', '', true, false, '', true, 'cass', false, 0, 1488948953084, 1495404778659, 0, e'==  ==\n - Tue, 07 Mar 2017\n21:07:25 EST\nhttp://www'),
