	('richard', 'changelog', 'url', 1, 'e52c2230-2a4d-11e7-b572-7831c1d422a2', '', '', '', '', '', 'go', 'a6744f3c-f008-11e6-a9c8-7831c1d422a2', 0, 'https://changelog.com/gotime', '', '', 0, 0, 0, 0, 0, '33f563cc1bf2fa5db316030ce458fac78819f27661490bfbd3eabe7fdf443d8d', '', true, false, '', true, 'cass', false, 0, 1493189970381, 1495404771470, 0, 'coming soon'),
	('richard', 'cli-menu', 'go', 2, 'f556c93e-1a6b-11e7-b251-7831c1d422a2', '', '', '', '', '', 'go', 'a6744f3c-f008-11e6-a9c8-7831c1d422a2', 0, e'package main\n\nimport (\n "fmt"\n "os"\n\n "github.com/paulrademacher/climenu"\n)\n\nfunc callback(id string) {\n fmt.Println("Chose item:", id)\n\n}\n\nfunc main() {\n menu := climenu.NewButtonMenu("Welcome", "Choose an action")\n menu.AddMenuItem("Create entry", "create")\n menu.AddMenuItem("Edit entry", "edit")\n\n action, escaped := menu.Run()\n if escaped {\n  os.Exit(0)\n }\n\n fmt.Println("action >", action)\n\n checkbox := climenu.NewCheckboxMenu("Let\'s try some checkboxes",\n  "Select options", "OK", "Cancel")\n checkbox.AddMenuItem("Apples", "apples")\n checkbox.AddMenuItem("Oranges", "oranges")\n checkbox.AddMenuItem("Bananas", "bananas")\n\n selection, escaped := checkbox.Run()\n if escaped {\n  os.Exit(0)\n }\n\n fmt.Println("selected >", selection)\n\n response := climenu.GetText("Say something interesting", "hi")\n if escaped {\n  os.Exit(0)\n }\n\n fmt.Printf("text > \\"%s\\"\\n", response)\n}', '', '', 1, 1491456012000, 0, 0, 0, '7376b6d7a66b5f1bf667904b717258e65584a372cb249ab5815b20dae579d6e8', '', true, false, '', true, 'cass', false, 0, 1491443673706, 1495404773122, 0, e'Welcome  \x1b[1mChoose an action\x1b[0m:\x1b[0m  \x1b[36m\x1b[0m'),
