	('richard', 'contains', 'txt', 3, 'f1561fb0-1728-11e7-9d54-7831c1d422a2', '', '', '', '', '', 'go', 'a6744f3c-f008-11e6-a9c8-7831c1d422a2', 0, e'func contains(in []string, val string) bool {\n    for _, x := range in {\n        if x == val {\n            return true\n        }\n    }\n    return false\n}\n', '', '', 0, 0, 0, 0, 0, 'f4bb58e0b3cc09ff01d099e9c878ddd4bb523fa1606f7b2256219e7f0dced323', '', true, false, '', true, 'cass', false, 0, 1491085067686, 1495404773884, 0, ''),
	('richard', 'diff', 'go', 2, '64c27fd2-2333-11e7-8bf7-7831c1d422a2', '', '', '', '', '', 'go', 'a6744f3c-f008-11e6-a9c8-7831c1d422a2', 0, e'package main\n\nimport (\n "fmt"\n "github.com/sergi/go-diff/diffmatchpatch"\n)\n\nconst (\n text1 = "Lorem ipsum dolor."\n text2 = "Lorem dolor sit amet."\n)\n\nfunc main() {\n dmp := diffmatchpatch.New()\n\n diffs := dmp.DiffMain(text1, text2, false)\n\n fmt.Println(dmp.DiffToDelta(diffs))\n}', '', '', 1, 1492409778000, 0, 0, 0, 'ede19cac27b93e2f98501d44e6695a9c7ad16c7fa5c39ca4d71751ff82c5281e', '', true, false, '', true, 'cass', false, 0, 1492409001693, 1495404772006, 0, e'=6-6=5+ sit amet=1\x1b[0m'),
