	('richard', 'exposing-go', 'url', 5, '5dcaa84a-dbbb-11e6-87cc-da2d562f8fc0', '', '', '', '', '', 'go', 'a6744f3c-f008-11e6-a9c8-7831c1d422a2', 0, 'https://blog.cloudflare.com/exposing-go-on-the-internet/', '', '', 0, 0, 0, 0, 0, 'a0471487bec5ba88b69e6787bd0f0485bf047f740039e11a895b8f5bfde1f344', '', true, false, '', true, '', false, 0, 1503539401724, 1503539401724, 1503539401724, e'So you want to expose Go on the Internet\n\nThis piece was originally written for the Gopher Academy advent series. We are grateful to them for allowing us to republish it here.'),
	('richard', 'ferret', 'go', 1, '8c0e06c4-3fb3-4b29-bc8e-98f77275cd4b', '', '', '', '', '', 'go', 'a6744f3c-f008-11e6-a9c8-7831c1d422a2', 0, e'package main\n\t\t\timport "fmt"\n\t\t\tfunc main() {\n\t\t\t    fmt.Println("Hello Go.")\n\t\t\t}\n\t\t\t', '', '', 0, 0, 0, 0, 0, '5668c76719b3f5186dd29ffbf991a56f87629f04baa287138aaa513dd8205413', '', true, false, '', false, 'map[v:v0.8.19+50954ce host:Richards-MacBook-Pro.local os:darwin agnt:<not implemented> addr:[::1]:57451]', false, 0, 1502923530245, 1502923530245, 1502923530245, ''),
	('richard', 'ferret', 'go', 2, '8c0e06c4-3fb3-4b29-bc8e-98f77275cd4b', '', '', '', '', '', 'go', 'a6744f3c-f008-11e6-a9c8-7831c1d422a2', 0, e'package main\n\nimport (\n\t"fmt"\n\t"github.com/argusdusty/Ferret"\n)\n\n// Some words to search for and return\nvar ExampleWords = []string{\n\t"abdeblah",\n\t"foobar",\n\t"barfoo",\n\t"qwerty",\n\t"testing",\n\t"example",\n\t"dictionary",\n\t"dvorak",\n\t"ferret",\n}\n\n// Length of data\nvar ExampleData = []interface{}{\n\t[]uint64{8},\n\t[]uint64{6},\n\t[]uint64{6},\n\t[]uint64{6},\n\t[]uint64{7},\n\t[]uint64{7},\n\t[]uint64{10},\n\t[]uint64{6},\n\t[]uint64{6},\n}\n\nvar ExampleCorrection = func(b []byte) [][]byte { return ferret.ErrorCorrect(b, ferret.LowercaseLetters) }\nvar ExampleSorter = func(s string, v interface{}, l int, i int) float64 { return -float64(l + i) }\nvar ExampleConverter = func(s string) []byte { return []byte(s) }\n\nfunc main() {\n\tExampleSearchEngine := ferret.New(ExampleWords, ExampleWords, ExampleData, ExampleConverter)\n\tfmt.Println(ExampleSearchEngine.Query("ar", 5))\n\tfmt.Println(ExampleSearchEngine.Query("test", 5))\n\tfmt.Println(ExampleSearchEngine.ErrorCorrectingQuery("tsst", 5, ExampleCorrection))\n\tfmt.Println(ExampleSearchEngine.SortedErrorCorrectingQuery("tsst", 5, ExampleCorrection, ExampleSorter))\n\tfmt.Println(ExampleSearchEngine.SortedQuery("a", 5, ExampleSorter))\n\tfmt.Println(ExampleSearchEngine.Query("a", 5))\n\tExampleSearchEngine.Insert("asdfghjklqwertyuiopzxcvbnm", "asdfghjklqwertyuiopzxcvbnm", []uint64{26})\n\tfmt.Println(ExampleSearchEngine.Query("sdfghjklqwert", 5))\n\tfmt.Println(ExampleSearchEngine.Query("ferret", 5))\n\tExampleSearchEngine.Insert("ferret", "ferret", []uint64{7})\n\tfmt.Println(ExampleSearchEngine.Query("ferret", 5))\n\n\tfmt.Println(ExampleSearchEngine.Query("e", -1))\n\tfmt.Println(ExampleSearchEngine.SortedQuery("e", -1, ExampleSorter))\n\tfmt.Println(ExampleSearchEngine.ErrorCorrectingQuery("e", -1, ExampleCorrection))\n\tfmt.Println(ExampleSearchEngine.SortedErrorCorrectingQuery("e", -1, ExampleCorrection, ExampleSorter))\n}', '', '', 1, 1502923592834, 0, 2, 0, 'e42b1a6940565521f13ad0640c5dbd40253c1dc49217af5655bb979f15199f79', '', true, false, '', true, '', false, 0, 1502923546360, 1502923546360, 1502923592834, e'[foobar barfoo dictionary] [[6] [6] [10]]  [t\x1b[0m'),
