	('richard', 'slicetricks', 'url', 2, 'a3941d2b-d6f1-11e6-94d6-8694c1045087', '', '', '', '', '', 'go', 'a6744f3c-f008-11e6-a9c8-7831c1d422a2', 0, 'https://github.com/golang/go/wiki/SliceTricks', '', '', 0, 0, 0, 0, 0, '1447e0f1ce493fe81457889f96da858c9d12974390193fc2f1c924ddd2b5e383', '', true, false, '', false, '', false, 0, 1503539456678, 1503539456678, 1503539456678, e'SliceTricks \u00B7 golang/go Wiki \u00B7 GitHub\n\nSince the introduction of the append built-in, most of the functionality of the container/vector package, which was removed in Go 1, can be replicated using append and copy.'),
