	('richard', 'slicetricks', 'url', 5, 'a3941d2b-d6f1-11e6-94d6-8694c1045087', '', '', '', '', '', 'go', 'a6744f3c-f008-11e6-a9c8-7831c1d422a2', 0, 'https://github.com/golang/go/wiki/SliceTricks', '', '', 0, 0, 0, 0, 0, '1447e0f1ce493fe81457889f96da858c9d12974390193fc2f1c924ddd2b5e383', '', true, false, '', false, '', false, 0, 1503540017575, 1503540017575, 1503540017575, e'<strong>SliceTricks \u00B7 golang/go Wiki \u00B7 GitHub<strong><p>Since the introduction of the append built-in, most of the functionality of the container/vector package, which was removed in Go 1, can be replicated using append and copy.</p><p>Here are the vector methods and their slice-manipulatio...</p>'),
	('richard', 'slicetricks', 'url', 6, 'a3941d2b-d6f1-11e6-94d6-8694c1045087', '', '', '', '', '', 'go', 'a6744f3c-f008-11e6-a9c8-7831c1d422a2', 0, 'https://github.com/golang/go/wiki/SliceTricks', '', '', 0, 0, 0, 0, 0, '1447e0f1ce493fe81457889f96da858c9d12974390193fc2f1c924ddd2b5e383', '', true, false, '', true, '', false, 0, 1503540061858, 1503540061858, 1503540061858, e'<strong>SliceTricks \u00B7 golang/go Wiki \u00B7 GitHub</strong><p>Since the introduction of the append built-in, most of the functionality of the container/vector package, which was removed in Go 1, can be replicated using append and copy.</p><p>Here are the vector methods and their slice-manipulati...</p>'),
	('richard', 'spawn', 'go', 2, '52073802-1efc-11e7-9840-7831c1d422a2', '', '', '', '', '', 'go', 'a6744f3c-f008-11e6-a9c8-7831c1d422a2', 0, e'// Sometimes our Go programs need to spawn other, non-Go\n// processes. For example, the syntax highlighting on this\n// site is [implemented](https://github.com/mmcgrana/gobyexample/blob/master/tools/generate.go)\n// by spawning a [](http://pygments.org/)\n// process from a Go program. Let\'s look at a few examples\n// of spawning processes from Go.\n\npackage main\n\nimport "fmt"\nimport "io/ioutil"\nimport "os/exec"\n\nfunc main() {\n\n    // We\'ll start with a simple command that takes no\n    // arguments or input and just prints something to\n    // stdout. The  helper creates an object\n    // to represent this external process.\n    dateCmd := exec.Command("date")\n\n    //  is another helper that handles the common\n    // case of running a command, waiting for it to finish,\n    // and collecting its output. If there were no errors,\n    //  will hold bytes with the date info.\n    dateOut, err := dateCmd.Output()\n    if err != nil {\n        panic(err)\n    }\n    fmt.Println("> date")\n    fmt.Println(string(dateOut))\n\n    // Next we\'ll look at a slightly more involved case\n    // where we pipe data to the external process on its\n    //  and collect the results from its .\n    grepCmd := exec.Command("grep", "hello")\n\n    // Here we explicitly grab input/output pipes, start\n    // the process, write some input to it, read the\n    // resulting output, and finally wait for the process\n    // to exit.\n    grepIn, _ := grepCmd.StdinPipe()\n    grepOut, _ := grepCmd.StdoutPipe()\n    grepCmd.Start()\n    grepIn.Write([]byte("hello grep\\ngoodbye grep"))\n    grepIn.Close()\n    grepBytes, _ := ioutil.ReadAll(grepOut)\n    grepCmd.Wait()\n\n    // We ommited error checks in the above example, but\n    // you could use the usual  pattern for\n    // all of them. We also only collect the \n    // results, but you could collect the  in\n    // exactly the same way.\n    fmt.Println("> grep hello")\n    fmt.Print    fmt.Print    es))\n\n    // Note that when spawning commands we need to\n    // provide an explicitly delineated command and\n    // argument array, vs. being able to just pass in one\n    // command-line string. If you want to spawn a full\n    // command w    // command w    // command w    // comm // option:\n    lsCmd := exec.Command("bash", "-c", "ls -a -l -h")\n    lsOut, err := lsCmd.Output()\n    if err != nil {\n        panic(err)\n    }\n    fmt.Println("> ls -a -l -h")\n    fmt.Println(string(lsOut))\n}\n', '', '', 2, 1496723404030, 0, 1, 0, 'd905f1da1dbdb9097107b5aacdbba3628e0f401c7ff1866199edc6a6d035786a', '', true, false, '', false, 'cass', false, 0, 1491945736479, 1495404772390, 1496723404030, e'# command-line-arguments  /Users/rjarmstrong/\x1b[0m'),
