	('richard', 'kwk-complete', 'sh', 10, '84e0a300-ccb5-11e6-8e2a-27249dd1b81b', '', '', '', '', '', 'kwk', 'c4a7f65f-efeb-11e6-a9bf-7831c1d422a2', 0, e'_kwk()  \n{\n# variables to hold existing words. \nlocal cur prev opts \n\n# array variable listing completions\nCOMPREPLY=()  \ncur="${COMP_WORDS[COMP_CWORD]}"  \nprev="${COMP_WORDS[COMP_CWORD-1]}"  \ncmds="find view edit move clone delete"\ngflags="--covert --debug --naked --ansi" \n\n  case "$cur" in\n    view)\n    COMPREPLY=( $( compgen -W "tmap.sh killport.sh" -- ${cur}) );;\n    -*)\n    COMPREPLY=( $( compgen -W "${gflags}" -- ${cur}) );;\n    *)\n    COMPREPLY=( $( compgen -W "${cmds}" -- ${cur}) );;\n  esac\n\nreturn 0   \n}\n\ncomplete -F _kwk kwk', '', '', 1, 1491468694000, 0, 0, 0, 'd5fd4c5eb3fea1abbf96f956f8ebd14de252b1fba0f63bfa0311c9e6ab2ffd3a', '', false, false, '', true, 'cass', false, 0, 1491468584294, 1495404772951, 0, ''),
