	('richard', 'algo-books', 'txt', 1, '0ae09a7a-be8c-4f56-8ce0-d9c586ed97d7', '', '', '', '', '', 'learn', '94b78f43-b593-4b17-b5a7-3137ce198216', 0, '', '', '', 0, 0, 0, 0, 0, 'e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855', '', true, false, '', false, 'map[addr:[::1]:54506 v:v0.8.19+50954ce host:Richards-MacBook-Pro.local os:darwin agnt:<not implemented>]', false, 0, 1502914404454, 1502914404454, 1502914404454, ''),
	('richard', 'algo-books', 'txt', 2, '0ae09a7a-be8c-4f56-8ce0-d9c586ed97d7', '', '', '', '', '', 'learn', '94b78f43-b593-4b17-b5a7-3137ce198216', 0, e'// BOOKS\nCLRS - Cormen, Leiserson, Rivest, and Stein, Introduction to Algorithms (3rd edition)\nDPV - Dasgupta, Papadimitriou, and Vazirani, Algorithms\nKT - Kleinberg and Tardos, Algorithm Design\nSW - Sedgewick and Wayne, Algorithms (4th edition)\n', '', '', 1, 1502918781576, 0, 1, 0, '5420d44fc3dbc712a410e57fcd4ba63151e2a10313758b9bbcb55bc002c49b0c', '', true, false, '', false, '', false, 0, 1502914408819, 1502914408819, 1502918781576, e'\x1b[0m'),
	('richard', 'algo-books', 'txt', 3, '0ae09a7a-be8c-4f56-8ce0-d9c586ed97d7', '', '', '', '', '', 'learn', '94b78f43-b593-4b17-b5a7-3137ce198216', 0, e'// BOOKS\nCLRS - Cormen, Leiserson, Rivest, and Stein, Introduction to Algorithms (3rd edition)\nGreat overview, algorithms course follows structure\n\nDPV - Dasgupta, Papadimitriou, and Vazirani, Algorithms\nNot as popular and sparser\n\nKT - Kleinberg and Tardos, Algorithm Design\nNot as highly rated\n\nSW - Sedgewick and Wayne, Algorithms (4th edition)\nGood diagrams also highly rated', '', '', 1, 1502918781576, 0, 0, 0, '4cc174c159cb0a0317dd715e554da8bab6fdaf9f06a4e69874d4c15dc7d1017a', '', true, false, '', true, '', false, 0, 1502920057215, 1502920057215, 1502920057215, e'\x1b[0m'),
