	('richard', 'algos', 'txt', 2, 'dcf675ee-f1ab-448b-ab6c-d60165969965', '', '', '', '', '', 'learn', '94b78f43-b593-4b17-b5a7-3137ce198216', 0, 'https://www.coursera.org/specializations/algorithms?action=enroll', '', '', 1, 1499672030827, 0, 2, 0, '449bd85080d8ebd644515e1e3ad12cf9f255b36b91850765269c46c284696a59', '', true, false, '', false, '', false, 0, 1499664426303, 1500756269735, 1500756269735, e'\x1b[0m'),
	('richard', 'algos', 'txt', 3, 'dcf675ee-f1ab-448b-ab6c-d60165969965', '', '', '', '', '', 'learn', '94b78f43-b593-4b17-b5a7-3137ce198216', 0, e'https://ocw.mit.edu/courses/electrical-engineering-and-computer-science/6-042j-mathematics-for-computer-science-spring-2015/index.htm\nhttps://www.coursera.org/specializations/algorithms?action=enroll', '', '', 1, 1500673452290, 0, 2, 0, '5ea4c5cec2db2528204fe68bd751a656329c1dc9aa8334dafddfd8ad8ae79283', '', true, false, '', false, '', false, 0, 1499675170396, 1500756269735, 1500756269735, e'\x1b[0m'),
	('richard', 'algos', 'txt', 4, 'dcf675ee-f1ab-448b-ab6c-d60165969965', '', '', '', '', '', 'learn', '94b78f43-b593-4b17-b5a7-3137ce198216', 0, e'// BLOOM\nhttps://github.com/tylertreat/BoomFilters\n- tunable\n\ngithub.com/yourbasic/bloom\n - many false positives, not tenable\n\nhttps://github.com/dataence/bloom\n- no viewed\n\nhttps://github.com/seiflotfy/cuckoofilter\n\n// BITSETS in go\nhttps://github.com/willf/bitset\n(intersections etc with bit sets unlike math big)\n\n\n\n// Rabin-karp\ngithub.com/glkz/rabinkarp\n- Returns the strings it finds - want the indices rather\n\n// Maths for com sci\nhttps://ocw.mit.edu/courses/electrical-engineering-and-computer-science/6-042j-mathematics-for-computer-science-spring-2015/index.htm\n\n// Coursera course\nhttps://www.coursera.org/specializations/algorithms?action=enroll', '', '', 2, 1500674163600, 0, 1, 0, 'd3d420c409832e81b32b3702d929503144ac3f39a90e182dad364cbed5d70561', '', true, false, '', false, '', false, 0, 1500674158443, 1500756269735, 1500756269735, e'The file // BLOOM  https://github.com/tylertr\x1b[0m'),
