	('richard', 'grpc-lb', 'txt', 1, '07ffc171-7a31-490a-ae66-03e2fa852991', '', '', '', '', '', 'net', 'ed3db64a-ef17-11e6-9085-7831c1d422a2', 0, e'global\n  log 127.0.0.1 local2 debug\n\ndefaults\n  log global\n  mode tcp #http\n  #option  httplog\n  option  dontlognull\n  retries 3\n  option redispatch\n  timeout connect  5000\n  timeout client  50000\n  timeout server  50000\n\n# accept connections on port 8080, forward requests to "http_cluster"\nfrontend http\n  bind :8080\n  default_backend http_cluster\n\n# HTTP server running on port 8000\nbackend http_cluster\n  balance roundrobin\n  option httpclose\n  #option forwardfor\n  server srv01 127.0.0.1:8083\n  server srv02 127.0.0.1:8084\n', '', '', 1, 1498957072499, 0, 2, 0, 'f19697849455188919be14211569e3aa23aec6b6e239d4f62667891931721807', '', true, false, '', false, 'map[v:v0.8.16+b2066c3 host:Richards-MacBook-Pro.local os:darwin agnt:<not implemented> addr:[::1]:54861]', false, 0, 1498944853883, 1498944853883, 1498957072499, e'\x1b[0m'),
