	('richard', 'pipe', 'go', 5, '84661bd0-ccb5-11e6-8e2a-27249dd1b81b', '', '', '', '', 'Not working for some reason', 'pipe', 'a0715df2-ef17-11e6-9084-7831c1d422a2', 0, e'package main\n\nimport "os"  \nimport "fmt"  \nimport "bufio"  \n  \nfunc main() { \n    s := bufio.NewScanner(os.Stdin)  \n    for s.Scan() {  \n        fmt.Println("line", s.Text())  \n    }  \n}  \n', '', e'\n\x0e\n\nlinebyline\x10\x01', 2, 0, 0, 2, 0, '4bae9866b86e4a029da26794ebd57e8c6094b791995f08a392fb4a1998a91820', '', true, false, '', true, 'cass', false, 0, 1484192101334, 1495404780032, 0, e'signal: interrupt\x1b[0m'),
	('richard', 'pipe', 'java', 1, '84707c10-ccb5-11e6-8e2a-27249dd1b81b', '', '', '', '', '', 'pipe', 'a0715df2-ef17-11e6-9084-7831c1d422a2', 0, e'import java.util.Scanner;  \n  \npublic class Solution {  \n  \n    public static void main(String[] args) {  \n        Scanner scan = new Scanner(System.in);  \n        int i = scan.nextInt();  \n  \n        // Write your code here.  \n  \n        System.out.println("String: " + s);  \n        System.out.println("Double: " + d);  \n        System.out.println("Int: " + i);  \n    }  \n}  \n', '', e'\n\x0e\n\nlinebyline\x10\x01', 0, 0, 0, 0, 0, 'c769445817ddbfa9ad3a6ffd77050993bafff882ec7f4e4c35ca993a9e6294be', '', true, false, '', true, 'cass', false, 0, 1472774400000, 1495404783995, 0, ''),
	('richard', 'pipe', 'php', 2, '845f3e00-ccb5-11e6-8e2a-27249dd1b81b', '', '', '', '', '', 'pipe', 'a0715df2-ef17-11e6-9084-7831c1d422a2', 0, e'while($f = fgets(STDIN)){  \n    echo "line: $f";  \n}', '', e'\n\x0e\n\nlinebyline\x10\x01', 1, 0, 0, 2, 0, '9f3e21552d6251132267914efd5aa44404e01a0cef6e7dd8a252d34434f8b117', '', true, false, '', true, 'cass', false, 0, 1484191792073, 1495404780055, 0, e'line: hello\x1b[0m'),
	('richard', 'pipe', 'py', 1, 'ff19c035-f0c8-11e6-9e20-7831c1d422a2', '', '', '', '', '', 'pipe', 'a0715df2-ef17-11e6-9084-7831c1d422a2', 0, e'  import sys  \\n  \\nfor line in sys.stdin:  \\n    print "line: " + line  \\n', '', '', 0, 1492032386000, 0, 0, 0, 'b08c1db104724ea742f3114ed85d96fff039669739ddac82171310b34aab4dc8', '', true, false, '', true, 'cass', false, 0, 1486865674538, 1495404779455, 0, ''),
	('richard', 'pipe', 'rs', 1, '2657e423-f0c9-11e6-9e21-7831c1d422a2', '', '', '', '', '', 'pipe', 'a0715df2-ef17-11e6-9084-7831c1d422a2', 0, e'  use std::io;  \\nuse std::io::prelude::*;  \\n  \\nfn main() {  \\n    let stdin = io::stdin();  \\n    for line in stdin.lock().lines() {  \\n        println!("{}", line.unwrap());  \\n    }  \\n}  \\n', '', '', 0, 0, 0, 0, 0, '08293de42d924a8265c4ba84aa9953634a5eec21e29d519f24bf8e89c8d1439b', '', true, false, '', true, 'cass', false, 0, 1486865740376, 1495404779435, 0, ''),
	('richard', 'pipe2', 'java', 1, '8469c550-ccb5-11e6-8e2a-27249dd1b81b', '', '', '', '', '', 'pipe', 'a0715df2-ef17-11e6-9084-7831c1d422a2', 0, e'package main  \n  \nimport "os"  \nimport "log"  \nimport "io/ioutil"  \n  \nfunc main() {  \n    bytes, err := ioutil.ReadAll(os.Stdin)  \n  \n    log.Println(err, string(bytes))  \n}  \n', '', e'\n\f\n\balllines\x10\x01', 0, 0, 0, 0, 0, '4687bc3356b09869b91bf9577908976a4ab94c86710da963dd62f05be5ae2f33', '', true, false, '', true, 'cass', false, 0, 1479168000000, 1495404782852, 0, ''),
	('richard', 'pythonpipe', 'sh', 1, '8446fb10-ccb5-11e6-8e2a-27249dd1b81b', '', '', '', '', '', 'pipe', 'a0715df2-ef17-11e6-9084-7831c1d422a2', 0, e'curl --silent \'[param1]\' | python -c "import sys, json; print json.load(sys.stdin)[\'[param2]\']"', '', '', 0, 1492032358000, 0, 0, 0, '52ecbb18f0d539b6847fc9099fe8735196e5c1574f0a1206456b91cb6267f356', '', true, false, '', true, 'cass', false, 0, 1472774400000, 1495404784022, 0, ''),
	('richard', 'readline', 'js', 3, '8462e780-ccb5-11e6-8e2a-27249dd1b81b', '', '', '', '', '', 'pipe', 'a0715df2-ef17-11e6-9084-7831c1d422a2', 0, e'var readline = require(\'readline\');  \nvar rl = readline.createInterface({  \n  input: process.stdin,  \n  output: process.stdout,  \n  terminal: false  \n});  \n  \nrl.on(\'line\', function(line){  \n    console.log(line + "zing");  \n})  \n', '', e'\n\x0e\n\nlinebyline\x10\x01', 0, 0, 0, 0, 0, 'e9e5b55fc44ab9188efb66a915e6607752a628252d2086bddba0b89a197dcdf4', '', true, false, '', true, 'cass', false, 0, 1489003642274, 1495404778378, 0, ''),
	('richard', 'coltemplate', 'sh', 1, '84b218f0-ccb5-11e6-8e2a-27249dd1b81b', '', '', '', '', '', 'printers', '2263207d-f008-11e6-a9c5-7831c1d422a2', 0, e'line=""  \ncount=0  \nwhile read a; do  \ncount =(($count + 1))  \necho $count  \n    if [[ (($count % 10)) -eq 0 ]]; then   \n       echo $line  \n    else   \n     line = "${line}${a}"  \n    fi  \ndone', '', '', 0, 0, 0, 0, 0, 'b5411ea7b22e54d4c0c4b5c6cea2aaccf15157db9d3db0b1c47b7fbbc641b470', '', true, false, '', true, 'cass', false, 0, 1472774400000, 1495404783879, 0, ''),
	('richard', 'format-as-n-cols', 'js', 1, '84b65eb0-ccb5-11e6-8e2a-27249dd1b81b', '', '', '', '', '', 'printers', '2263207d-f008-11e6-a9c5-7831c1d422a2', 0, e'var readline = require(\'readline\');  \nvar rl = readline.createInterface({  \n  input: process.stdin,  \n  output: process.stdout,  \n  terminal: false  \n});  \n  \nvar cols = process.argv[1] || 5;  \n  \nconsole.log(\'Cols:\', cols);  \n  \nvar newline = [];  \nrl.on(\'line\', function(line){  \n     if (line !== null) {  \n    newline.push(line)  \n                 if (newline.length % cols == 0) {  \n                     process.stdout.write(newline.join(\' \') + \'\\n\');  \n                          newline = []  \n    }  \n              }  \n})', '', '', 0, 0, 0, 0, 0, 'c8679be42fd49d2e85d551630ab9b3942b0095e404dfabba7a3ef8ccd40c2d2f', '', true, false, '', true, 'cass', false, 0, 1479081600000, 1495404782961, 0, ''),
	('richard', 'graph-stats', 'go', 39, 'f69b6760-043a-11e7-ad92-7831c1d422a2', '', '', 'richard/pipe.go', '', '', 'printers', '2263207d-f008-11e6-a9c5-7831c1d422a2', 0, e'package main\n\nimport "os"\nimport "fmt"\nimport "bufio"\nimport "strconv"\nimport "regexp"\nimport "strings"\n\nconst (\n        margin = "   "\n)\n\nfunc main() {\n        s := bufio.NewScanner(os.Stdin)\n        r := regexp.MustCompile(" {2,}")\n        count := 0\n        for s.Scan() {\n                if count%3 == 0 {\n                        fmt.Print("\\x1b[2J\\x1b[H")\n                        fmt.Println("")\n                        fmt.Println(margin,"Docker CPU usage.")\n                        fmt.Println("")\n                }\n                line := s.Text()\n                if strings.Contains(line,"CONTAINER") {\n                        continue\n                }\n                cols := r.Split(line, -1)\n                c := strings.Replace(cols[1], "%", "", -1)\n                cpu, err := strconv.ParseFloat(c, 32)\n                if err != nil {\n                        panic(err)\n                }\n                fmt.Printf("%s %s| %6.2f%% %s\\n",  margin, cols[0], cpu, strings.Repeat("\U00002589", int(cpu)))\n                count += 1\n        }\n}', '', e'\n\x0e\n\nlinebyline\x10\x01', 1, 1492408810000, 0, 0, 0, '4a8350f6e810ab05a4f19eb86121dd09bccd939868ae932c13cb6e7d47bc35cf', '', true, false, '', true, 'cass', false, 0, 1491896926222, 1495404772438, 0, ''),
	('richard', 'pretty-json', 'go', 8, '66adfd54-0a1d-11e7-85ad-7831c1d422a2', '', '', '', '', '', 'printers', '2263207d-f008-11e6-a9c5-7831c1d422a2', 0, e'package main\n\nimport (\n\t"encoding/json"\n\t"fmt"\n\t"os"\n)\n\nfunc main() {\n\td := json.NewDecoder(os.Stdin)\n\td.Token()\n\tfor d.More() {\n\t\ts, _ := d.Token()\n\t\tfmt.Printf("%v", s)\n\t}\n\td.Token()\n}\n', '', '', 1, 1491104947000, 0, 0, 0, 'a628211057cfbbe2a36ec2c024457278cb49c852140e0bd227fcbddafedd7a9f', '', true, false, '', true, 'cass', false, 0, 1489653831244, 1495404777571, 0, e'snippets{aliases{\x1b[0m'),
