	('richard', 'pretty-json', 'py', 2, '88e048bc-0a14-11e7-85ac-7831c1d422a2', '', '', '', '', '', 'printers', '2263207d-f008-11e6-a9c5-7831c1d422a2', 0, e'import fileinput, json;\n\nprint json.dumps(json.loads("".join(fileinput.input())),\n                 sort_keys=True, indent=4, ensure_ascii=False)', '', '', 1, 1497327232268, 0, 5, 0, '1a780e6751405e13d10692cbdf7990064706353f217bd374d8d53cd1f9f7a2b5', '', true, false, '', true, 'cass', false, 0, 1489646931617, 1495404777587, 1497327232268, e'{      "accountId": "1a5",       "assignServi\x1b[0m'),
	('richard', 'print-unicode', 'js', 55, 'dc7babbb-050e-11e7-9380-7831c1d422a2', '', '', 'richard/dingbats.js', '', '', 'printers', '2263207d-f008-11e6-a9c5-7831c1d422a2', 0, e'var startHex = process.argv[1]; \nvar endHex =  process.argv[2];\nif (!startHex || !endHex) {\n  throw new Error(\'hex values for start and end required e.g. `print-unicode.js \\x2700 \\x27BF`\');\n}\nvar count = 0;\nvar start = parseInt(startHex, 16)\nvar end = parseInt(endHex, 16)\nfor(var i=start; i<=end; i++){\n    if(count == 0) process.stdout.write(\'\\n  \');\n    process.stdout.write(util.format(\'%s  \\033[2m%s\\033[0m   \', String.fromCodePoint(i), i.toString(16))); \n    if(++count%10==0) process.stdout.write(\'\\n  \');  \n}  \nprocess.stdout.write(\'\\n\\n\');', '', e'\n\x0b\n\x07symbols\x10\x01', 1, 0, 0, 46, 0, '68a4f8a5e9308a9b0a01368779a4e1b75f850fa087f6c23da96dd8a3e43853e5', '', true, false, '', false, 'cass', false, 0, 1491547177662, 1497310323409, 1497310323409, e'\U0000A500  \x1b[2ma500\x1b[0m   \U0000A501  \x1b[2ma501\x1b[0m   \U0000A502  \x1b[2ma5\x1b[0m'),
