	('richard', 'print-unicode', 'txt', 31, '16618f04-051d-11e7-a09e-7831c1d422a2', '', '', '', '', '', 'printers', '2263207d-f008-11e6-a9c5-7831c1d422a2', 0, e'#!/bin/sh\n#\n# hexcount -  POSIX Shell script to count from $1 to $2 in hex,\n#             separated by ";" and with the precision set to the\n#             maximum digits of $1 and $2.\n# Usage:      hexcount lo hi\n# Example:    hexcount FFF 1200\n\nfrom=$0 to=$1\nfrom=$(printf \'%d\' "0x$from") to=$(printf \'%d\' "0x$to")\nwhile test "$from" -le "$to"; do\n    hex=$(echo "obase=16; ${from}" | bc)\n    printf \'\\\\x%s\' ${from^^}; echo -e\n    from=$((from+1))\ndone\nprintf \'\\n\'', '', '', 0, 1490079741000, 0, 0, 0, '797eb73db314474c913224874e4a1f90d1991dbb2b16bd0167684f3a12bcb78a', '', true, false, '', true, 'cass', false, 0, 1490079776387, 1495404776882, 0, e'00: line 14: ${from^^}: bad substitution\x1b[0m'),
	('richard', 'templates', 'sh', 3, '85502db0-ccb5-11e6-8e2a-27249dd1b81b', '', '', '', '', '', 'printers', '2263207d-f008-11e6-a9c5-7831c1d422a2', 0, e'line=""  \ncount=0  \nwhile read a; do  \ncount =(($count + 1))  \necho $count  \n    if [[ (($count % 10)) -eq 0 ]]; then   \n       echo $line  \n    else   \n     line = "${line}${a}"  \n    fi  \ndone', '', '', 2, 0, 0, 1, 0, 'b5411ea7b22e54d4c0c4b5c6cea2aaccf15157db9d3db0b1c47b7fbbc641b470', '', true, false, '', true, 'cass', false, 0, 1491547049586, 1495404772753, 0, e'/bin/bash: -c: line 5: syntax error near unex\x1b[0m'),
	('richard', 'print-to-screen', 'txt', 1, 'f707bb86-1f01-11e7-9842-7831c1d422a2', '', '', '', '', '', 'runtime', 'b958da0d-1f01-11e7-9841-7831c1d422a2', 0, 'Hello, plain text', '', '', 0, 1491951529000, 0, 0, 0, '9557dc2eb1e22adec0163b6828a4059d8cf68b89f81429575fadc81b1107de04', '', true, false, '', true, 'cass', false, 0, 1491947895799, 1495404772352, 0, ''),
	('richard', 'print-tree', 'go', 2, '27d730ef-1f21-11e7-9844-7831c1d422a2', '', '', '', '', '', 'runtime', 'b958da0d-1f01-11e7-9841-7831c1d422a2', 0, e'package main\n\nimport (\n    "github.com/mitchellh/go-ps"\n    "os"\n    "fmt"\n)\n\nfunc main() {\n    printTree(os.Getpid(), []string{})\n}\n\nfunc printTree(pid int, args []string) {\n    p, err := ps.FindProcess(pid)\n    if err != nil {\n        fmt.Println(err)\n        return\n    }\n    if p == nil || p.Pid() == 0 {\n        fmt.Println("DONE")\n        return\n    }\n    fmt.Println(p.Executable(), p.Pid(), args)\n    printTree(p.PPid(), nil)\n}\n', '', '', 1, 0, 0, 1, 0, 'f41ac40b07dc6e73177ac7ec2f7bd41bfbef66ad40cc05c1285930d442c55061', '', true, false, '', true, 'cass', false, 0, 1491961406172, 1495404772301, 0, e'richard-runtime- 28297 []  go 28289 []  kwk-d\x1b[0m'),
	('richard', 'sample', 'json', 1, '848def20-ccb5-11e6-8e2a-27249dd1b81b', '', '', '', '', '', 'samples', '907b5574-efee-11e6-a9c3-7831c1d422a2', 0, e'{  \n  "firstName": "John",  \n  "lastName": "Smith",  \n  "isAlive": true,  \n  "age": 25,  \n  "address": {  \n    "streetAddress": "21 2nd Street",  \n    "city": "New York",  \n    "state": "NY",  \n    "postalCode": "10021-3100"  \n  },  \n  "phoneNumbers": [  \n    {  \n      "type": "home",  \n      "number": "212 555-1234"  \n    },  \n    {  \n      "type": "office",  \n      "number": "646 555-4567"  \n    },  \n    {  \n      "type": "mobile",  \n      "number": "123 456-7890"  \n    }  \n  ],  \n  "children": [],  \n  "spouse": null  \n}  \n', '', '', 1, 1497240664807, 0, 1, 0, 'be502f1dfdd73166ab41df9387bafca0b0ad44a4e6ffcdd31ed92a44e723c742', '', true, false, '', true, 'cass', false, 0, 1472774400000, 1495404784055, 1497240664807, e'\x1b[0m'),
	('richard', 'sample', 'md', 2, 'd8b9dffc-0db7-11e7-a659-7831c1d422a2', '', '', '', '', '', 'samples', '907b5574-efee-11e6-a9c3-7831c1d422a2', 0, e'#gRPC-Go\n\n[![Build Status](https://travis-ci.org/grpc/grpc-go.svg)](https://travis-ci.org/grpc/grpc-go) [![GoDoc](https://godoc.org/google.golang.org/grpc?status.svg)](https://godoc.org/google.golang.org/grpc)\n\nThe Go implementation of [gRPC](http://www.grpc.io/): A high performance, open source, general RPC framework that puts mobile and HTTP/2 first. For more information see the [gRPC Quick Start](http://www.grpc.io/docs/) guide.', '', '', 1, 1497240674391, 0, 2, 0, '2ba2139e27a72ceeb5c4f00161ad168b11c3ad94146abf82031028717535c356', '', true, false, '', true, 'cass', false, 0, 1490046896250, 1495404776970, 1497240674391, e'\x1b[1;30;107mgRPC-Go \x1b[1;37m*******************\x1b[0m'),
	('richard', 'sample', 'rss', 2, 'c8ef754a-03a2-11e7-83b7-7831c1d422a2', '', '', '', '', '', 'samples', '907b5574-efee-11e6-a9c3-7831c1d422a2', 0, e'<xml version="1.0" encoding="UTF-8" ?>\n<rss xmlns:dc="http://purl.org/dc/elements/1.1/" version="2.0">\n   <channel>\n      <title>RSS title</title>\n      <link>http://www.example.com/</link>\n      <description>RSS description</description>\n      <language>en</language>\n      <item>\n         <title>News item title</title>\n         <link>http://www.example.com/link/to/news/item/</link>\n         <guid isPermaLink="true">identifier-5f4b02697d2006f72648ebd0d9c6ce96</guid>\n         <description>Full news item text.</description>\n         <pubDate>Fri, 01 Jul 2016 17:41:07 +0000</pubDate>\n      </item>\n   </channel>\n</rss>', '', '', 1, 1497240688740, 0, 1, 0, '04ee6c2beda5c7ed1a58949b7523a3e448aea5d8f9d0b3619b52a52329c5b2b4', '', true, false, '', true, 'cass', false, 0, 1488938339127, 1495404778704, 1497240688740, e'\x1b[0m'),
	('richard', 'sample', 'xml', 1, '849d7f80-ccb5-11e6-8e2a-27249dd1b81b', '', '', '', '', '', 'samples', '907b5574-efee-11e6-a9c3-7831c1d422a2', 0, e'<?xml version="1.0" encoding="iso-8859-1" ?>  \n<!DOCTYPE nzb PUBLIC "-//newzBin//DTD NZB 1.1//EN" "http://www.newzbin.com/DTD/nzb/nzb-1.1.dtd">  \n<nzb xmlns="http://www.newzbin.com/DTD/2003/nzb">  \n <head>  \n   <meta type="title">Your File!</meta>  \n   <meta type="tag">Example</meta>  \n </head>  \n <file poster="Joe Bloggs &lt;bloggs@nowhere.example&gt;" date="1071674882" subject="Heres your file!  abc-mr2a.r01 (1/2)">  \n   <groups>  \n     <group>alt.binaries.newzbin</group>  \n     <group>alt.binaries.mojo</group>  \n   </groups>  \n   <segments>  \n     <segment bytes="102394" number="1">123456789abcdef@news.newzbin.com</segment>  \n     <segment bytes="4501" number="2">987654321fedbca@news.newzbin.com</segment>  \n   </segments>  \n </file>  \n</nzb>  \n', '', e'\n\x0b\n\x07private\x10\x01', 0, 0, 0, 0, 0, '79e361b91f8004e3a323f51b0f3232d2506773a13cfe87d9495db598f599981b', '', true, false, '', true, 'cass', false, 0, 1472774400000, 1495404784073, 0, ''),
	('richard', 'ast-go', 'url', 1, 'd3166c1e-b7d4-404e-bd57-4640e26ca68c', '', '', '', '', '', 'search', '8d3bf2c3-15bf-11e7-9c8a-7831c1d422a2', 0, 'https://zupzup.org/go-ast-traversal/?utm_source=golangweekly', '', '', 0, 0, 0, 0, 0, 'a18b7ec6a75f2b19b3891d2ef8996715e137354f587e962c62586d43b497d7d6', '', true, false, '', true, 'map[agnt:<not implemented> addr:[::1]:58221 v:v0.8.18+f43032c host:Richards-MacBook-Pro.local os:darwin]', false, 0, 1500594464464, 1500594464464, 1500594464464, 'coming soon'),
	('richard', 'bleve', 'go', 34, '2d07390b-17ef-11e7-a5ed-7831c1d422a2', '', '', '', '', '', 'search', '8d3bf2c3-15bf-11e7-9c8a-7831c1d422a2', 0, e'package main\n\nimport (\n\t"fmt"\n\t"os"\n\t"github.com/blevesearch/bleve"\n\t"encoding/json"\n)\n\ntype Snipp struct {\n\tUsername string\n\tName     string\n\tExt      string\n\tPouch    string\n}\n\nfunc (s Snipp) Type() string {\n\treturn "snipp"\n}\n\nfunc main() {\n\n\tindexName := "example.bleve"\n\tvar index bleve.Index\n\tif _, err := os.Stat(indexName); os.IsNotExist(err) {\n\t\tmapping := bleve.NewIndexMapping()\n\t\tdocMapping := bleve.NewDocumentMapping()\n\t\tnameMap := bleve.NewTextFieldMapping()\n\t\tnameMap.Name = "name"\n\t\tdocMapping.AddFieldMappingsAt("name", nameMap)\n\t\tmapping.AddDocumentMapping("snipp", docMapping)\n\t\tindex, err = bleve.New(indexName, mapping)\n\t\tif err != nil {\n\t\t\tfmt.Println(err)\n\t\t\treturn\n\t\t}\n\t} else {\n\t\tindex, err = bleve.Open(indexName)\n\t}\n\n\t// index some data\n\tindex.Index("1", Snipp{ Name: "bleve", Ext:"go", Username:"richard",Pouch:"search", })\n\tindex.Index("2", Snipp{ Name: "blever", Ext:"go", Username:"richard",Pouch:"search", })\n\n\t// search for some text\n\tquery := bleve.NewPrefixQuery("ble")\n\treq := bleve.NewSearchRequest(query)\n\treq.Fields = []string{"Username", "Name", "Ext", "Pouch"}\n\treq.Highlight = bleve.NewHighlight()\n\treq.Highlight.AddField("Name")\n\tres, err := index.Search(req)\n\tif err != nil {\n\t\tfmt.Println(err)\n\t\treturn\n\t}\n\tjs, err := json.MarshalIndent(res, "", "  ")\n\tfmt.Printf("%s", string(js))\n\tfor _, v := range res.Hits {\n\t\tfmt.Printf("ID: %v. Score %v.\\n", v.ID, v.Score)\n\t\tfor k, v := range v.Fields {\n\t\t\tfmt.Printf("%v:%v.\\n", k, v)\n\t\t}\n\t\tfor k, v := range v.Fragments {\n\t\t\tfmt.Printf("%v:%v.\\n", k, v[0])\n\t\t}\n\t}\n}', '', '', 1, 1500621508732, 0, 2, 0, '411db96b4cfef162c33d1a9dca373cd5770af88b583f368c815702d5d7b083e5', '', true, false, '', true, 'cass', false, 0, 14911