	('richard', 'bash', 'url', 3, 'c9a23509-f233-11e6-b803-7831c1d422a2', '', '', '', '', '', 'shortcuts', 'c1baadd7-f1bd-11e6-b717-7831c1d422a2', 0, 'http://www.skorks.com/2009/09/bash-shortcuts-for-maximum-productivity/', '', '', 1, 1496516977858, 0, 1, 0, '45181b4f3f3afe730f97fc731285ca686ebd58aca6de446faa10adc8df902367', '', true, false, '', true, 'cass', false, 0, 1490746194001, 1495404775200, 1496516977858, e'\x1b[0m'),
