	('richard', 'vi-deleteline', 'txt', 1, '85c92e40-ccb5-11e6-8e2a-27249dd1b81b', '', '', '', '', '', 'shortcuts', 'c1baadd7-f1bd-11e6-b717-7831c1d422a2', 0, 'dd', '', '', 0, 0, 0, 0, 0, '9b7ecc6eeb83abf9ade10fe38865df4499be3568dcc507ae2ec3b44989cb0093', '', true, false, '', true, 'cass', false, 0, 1480896000000, 1495404781085, 0, ''),
	('richard', 'vim-cheat-sheet', 'url', 1, 'c1452dd2-f0c6-11e6-9087-7831c1d422a2', '', '', '', '', '', 'shortcuts', 'c1baadd7-f1bd-11e6-b717-7831c1d422a2', 0, 'http://www.viemu.com/vi-vim-cheat-sheet.gif', '', '', 0, 0, 0, 0, 0, 'f16e8f3f24bb336997b306bec51b557b65e470a5c6cba686c3d63dd37c02e5d0', '', true, false, '', true, 'cass', false, 0, 1486864711810, 1495404779472, 0, ''),
	('richard', 'jsonpivot', 'sql', 3, '1253f2ac-14ec-11e7-8b5b-7831c1d422a2', '', '', '', '', '', 'sql', 'fa953c71-14eb-11e7-8b54-7831c1d422a2', 0, e'-- MSSQL\nSELECT [A], [B], [C], [X] from\n(SELECT GroupAlphabet as g, 1 as score FROM ReEnrolmentsGroups WHERE ReEnrolmentID = \'F33D5B3A-3E84-E611-80CC-000D3AD01278\'\nUNION\nSELECT GroupAlphabet as g, 2 as score from RegistrarsGroupSettings WHERE RegistrarID = \'B3C3DBDC-643A-E611-80CE-000D3AD01D71\' and Semester = \'S1/2017\'\t\nUNION\nSELECT GroupName as g, 3 AS score from Placements WHERE RegistrarID = \'B3C3DBDC-643A-E611-80CE-000D3AD01D71\' and Semester = \'S1/2017\'\n ) AS raw pivot (\n  sum(score) FOR g IN ([A], [B], [C], [X])\n) as pt\nFOR JSON AUTO', '', '', 0, 1491530316000, 0, 0, 0, '6d2fd6e7cee55597a84bca62cdc95fa39dcd61c47a8a40c89d8ccfebb0bddf43', '', true, false, '', false, 'cass', false, 0, 1490839002914, 1495404775040, 0, ''),
	('richard', 'jsonpivot', 'sql', 4, '1253f2ac-14ec-11e7-8b5b-7831c1d422a2', '', '', '', '', '', 'sql', 'fa953c71-14eb-11e7-8b54-7831c1d422a2', 0, e'-- MSSQL\nSELECT [A], [B], [C], [X] from\n(SELECT GroupAlphabet as g, 1 as score FROM ReEnrolmentsGroups WHERE ReEnrolmentID = \'F33D5B3A-3E84-E611-80CC-000D3AD01278\'\nUNION\nSELECT GroupAlphabet as g, 2 as score from RegistrarsGroupSettings WHERE RegistrarID = \'B3C3DBDC-643A-E611-80CE-000D3AD01D71\' and Semester = \'S1/2017\'\t\nUNION\nSELECT GroupName as g, 3 AS score from Placements WHERE RegistrarID = \'B3C3DBDC-643A-E611-80CE-000D3AD01D71\' and Semester = \'S1/2017\'\n ) AS raw pivot (\n  sum(score) FOR g IN ([A], [B], [C], [X])\n) as pt\nFOR JSON AUTO', '', '', 1, 1500594721697, 0, 3, 0, '6d2fd6e7cee55597a84bca62cdc95fa39dcd61c47a8a40c89d8ccfebb0bddf43', '', true, false, '', true, '', false, 0, 1496387557412, 1496387557412, 1500594721697, e'\x1b[0m'),
	('richard', 'mysql-password', 'txt', 1, 'b760ae92-dda0-4725-9199-6a4631ffa583', '', '', '', '', '', 'sql', 'fa953c71-14eb-11e7-8b54-7831c1d422a2', 0, e'SET PASSWORD FOR \'bob\'@\'%.example.org\' =\n', '', '', 0, 0, 0, 0, 0, 'fcb812f7f719fe6ed1f991f1c133121b0801424b5fa03ea807e08418bfff46ed', '', true, false, '', false, 'map[v:v0.8.16+b2066c3 host:Richards-MacBook-Pro.local os:darwin agnt:<not implemented> addr:[::1]:59409]', false, 0, 1499217189805, 1499217189805, 1499217189805, ''),
	('richard', 'mysql-password', 'txt', 2, 'b760ae92-dda0-4725-9199-6a4631ffa583', '', '', '', '', '', 'sql', 'fa953c71-14eb-11e7-8b54-7831c1d422a2', 0, e'GRANT ALL ON cattle.* TO \'cattle\'@\'%\' IDENTIFIED BY \'password\';\nGRANT ALL ON cattle.* TO \'cattle\'@\'localhost\' IDENTIFIED BY \'password\';\n\nSET PASSWORD FOR \'bob\'@\'%.example.org\' = \'password\'\n', '', '', 0, 0, 0, 0, 0, '1c02441aea2d8dc5e7a60640cdf2649eed9cd022879ff0ab9d0dd0267a0def7a', '', true, false, '', true, '', false, 0, 1499217682256, 1499217682256, 1499217682256, ''),
	('richard', 'priority-grouping', 'sql', 2, '840a63b3-14ef-11e7-8b62-7831c1d422a2', '', '', '', '', '', 'sql', 'fa953c71-14eb-11e7-8b54-7831c1d422a2', 0, e'DECLARE @priority_groups table (\n\tgroupName nchar(1)\n)\nINSERT INTO @priority_groups (groupName) VALUES (\'X\'), (\'A\'), (\'B\'), (\'C\');\n\nSELECT DISTINCT ReEnrolmentID, \n\tReEnrolmentSemesterID,\n\tRegistrarID,\n\t(SELECT top 1 subregionid from Placements WHERE RegistrarID = r.RegistrarID and r.ReEnrolmentsemester = semester) as subregion,\n\tfte = \n\tCASE TrainingModeAbbreviation\n\tWHEN \'FT\' THEN 1\n\tWHEN \'PT\' THEN 0.5\n\tEND,\n\t(SELECT  GroupAlphabet + \', \' AS \'data()\' FROM ReEnrolmentsGroups WHERE ReEnrolmentID = r.ReEnrolmentID for xml path(\'\')) as preferred_groups,\n\t(SELECT  GroupAlphabet + \', \' AS \'data()\' from RegistrarsGroupSettings WHERE RegistrarID = r.RegistrarID and Semester = r.ReEnrolmentSemester for xml path(\'\')) limited_to_groups,\t\n\t(SELECT \'X,A,B,C\') As group_priority,\n\n\tCoalesce(\n\t\t-- constrained preferred\n\t\t(SELECT top 1 groupName from @priority_groups WHERE groupName IN (SELECT GroupAlphabet from RegistrarsGroupSettings where RegistrarID = r.RegistrarID AND SEMESTER = r.ReEnrolmentSemester\n\t\t  AND GroupAlphabet in (SELECT GroupAlphabet from ReEnrolmentsGroups where ReEnrolmentID = r.ReenrolmentId))\n\t), Coalesce(\n\t\t-- constrained\n\t\t(SELECT top 1 groupName from @priority_groups WHERE groupName IN (SELECT GroupAlphabet from RegistrarsGroupSettings where RegistrarID = r.RegistrarID AND SEMESTER = r.ReEnrolmentSemester)),\n\t\t-- preferred\n\t\t(SELECT top 1 groupName from @priority_groups WHERE groupName IN (SELECT GroupAlphabet from ReEnrolmentsGroups where ReEnrolmentID = r.ReenrolmentId))\n\t)) as grp\nfrom ReEnrolments r where ReEnrolmentSemesterID >= @fromSemesterId and reenrolmentterm = \'General Practice Training\';', '', '', 0, 0, 0, 0, 0, '2ce6fd75b46c7749173a3cb9ac23c00102f492fe720023e3d4ccba0bb5ac7ccf', '', true, false, '', true, '