	('richard', 'estimates', 'txt', 1, '2db9a2f3-9764-41fb-95c1-1fde6a69fb01', '', '', '', '', '', 'synergia', 'c9b2b5d8-f00c-11e6-99dd-7831c1d422a2', 0, '', '', '', 0, 0, 0, 0, 0, 'e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855', '', false, false, '', false, 'map[v:v0.8.19+50954ce host:Richards-MacBook-Pro.local os:darwin agnt:<not implemented> addr:[::1]:59414]', false, 0, 1501027608816, 1501027608816, 1501027608816, ''),
	('richard', 'estimates', 'txt', 2, '2db9a2f3-9764-41fb-95c1-1fde6a69fb01', '', '', '', '', '', 'synergia', 'c9b2b5d8-f00c-11e6-99dd-7831c1d422a2', 0, e'\n=== PDF printing ===\n\n** Maps\n\n** Charts\n\npackage main\n\nimport (\n    "github.com/jung-kurt/gofpdf"\n    "log"\n)\n\nfunc main() {\n    pdf := gofpdf.New("L", "mm", "A4", "")\n    pdf.AddPage()\n    pdf.SetFillColor(0, 120, 30)\n    pdf.SetTextColor(0, 120, 30)\n    pdf.SetFont("Times", "B", 16)\n    pdf.Text(5.0, 10, "Practice Numbers")\n    pdf.Rect(5.0, 21.0, 50.0, 20.0, "F")\n    pdf.Rect(5.0, 42.0, 124.0, 20.0, "F")\n    pdf.Rect(5.0, 63.0, 84.0, 20.0, "F")\n    pdf.Rect(5.0, 84.0, 10.0, 20.0, "F")\n    err := pdf.OutputFileAndClose("hello.pdf")\n    log.Fatal(err)\n}\n\n- Tables\n', '', '', 0, 0, 0, 0, 0, '80b87bd926b35ceebb894f45023cb714706b47e77e6be13b19c1670737f72efa', '', false, false, '', false, '', false, 0, 1501027945974, 1501027945974, 1501027945974, ''),
