	('richard', 'gpsyn-pdf', 'txt', 2, '721acb66-2146-46e8-aa14-e6d8de1a3e80', '', '', '', '', '', 'synergia', 'c9b2b5d8-f00c-11e6-99dd-7831c1d422a2', 0, e'Drawing maps:\n\nhttps://github.com/ajstarks/svgo\nPerhaps render svg -> image\n\nStraight ->\nImage ->\nhttps://github.com/signintech/gopdf\n\n\nhttps://github.com/llgcode/draw2d\n\n\n```\npackage main\n\nimport (\n\t"github.com/jung-kurt/gofpdf"\n\t"log"\n)\n\nfunc main() {\n\tpdf := gofpdf.New("L", "mm", "A4", "")\n\tpdf.AddPage()\n\tpdf.SetFillColor(0, 120, 30)\n\tpdf.SetTextColor(0, 120, 30)\n\tpdf.SetFont("Times", "B", 16)\n\tpdf.Text(5.0, 10, "Practice Numbers")\n\tpdf.Rect(5.0, 21.0, 50.0, 20.0, "F")\n\tpdf.Rect(5.0, 42.0, 124.0, 20.0, "F")\n\tpdf.Rect(5.0, 63.0, 84.0, 20.0, "F")\n\tpdf.Rect(5.0, 84.0, 10.0, 20.0, "F")\n\terr := pdf.OutputFileAndClose("hello.pdf")\n\tlog.Fatal(err)\n}\n```', '', '', 1, 1496901393247, 0, 1, 0, 'fa756da0cf551edc6835cbef1848bb453e9f5ff4ce6b2acd72959b9ac36eba23', '', false, false, '', false, '', false, 0, 1496901388548, 1501194062625, 1501194062625, e'\x1b[0m'),
	('richard', 'gpsyn-pdf', 'txt', 3, '721acb66-2146-46e8-aa14-e6d8de1a3e80', '', '', '', '', '', 'synergia', 'c9b2b5d8-f00c-11e6-99dd-7831c1d422a2', 0, e'Drawing maps:\n\nhttps://github.com/ajstarks/svgo\nPerhaps render svg -> imagehttps://stackoverflow.com/questions/26641273/how-to-write-a-polyline-in-golang\n\nStraight ->\nImage ->\nhttps://github.com/signintech/gopdf\n\n\nhttps://github.com/llgcode/draw2d\n\n// Import geojson\nhttps://github.com/paulmach/go.geojson\n\nhttps://github.com/kellydunn/golang-geo\n\n// Go library\nhttps://github.com/paulmach/go.geo\n\n```\npackage main\n\nimport (\n\t"github.com/jung-kurt/gofpdf"\n\t"log"\n)\n\nfunc main() {\n\tpdf := gofpdf.New("L", "mm", "A4", "")\n\tpdf.AddPage()\n\tpdf.SetFillColor(0, 120, 30)\n\tpdf.SetTextColor(0, 120, 30)\n\tpdf.SetFont("Times", "B", 16)\n\tpdf.Text(5.0, 10, "Practice Numbers")\n\tpdf.Rect(5.0, 21.0, 50.0, 20.0, "F")\n\tpdf.Rect(5.0, 42.0, 124.0, 20.0, "F")\n\tpdf.Rect(5.0, 63.0, 84.0, 20.0, "F")\n\tpdf.Rect(5.0, 84.0, 10.0, 20.0, "F")\n\terr := pdf.OutputFileAndClose("hello.pdf")\n\tlog.Fatal(err)\n}\n```', '', '', 1, 1496901393247, 0, 0, 0, 'a16fe38ce382cebf09c4f1b534f5fb9e5dda42b3a869b8f6c797690ec60c4218', '', false, false, '', false, '', false, 0, 1496902546961, 1501194062625, 1501194062625, e'\x1b[0m'),
	('richard', 'gpsyn-pdf', 'txt', 4, '721acb66-2146-46e8-aa14-e6d8de1a3e80', '', '', '', '', '', 'synergia', 'c9b2b5d8-f00c-11e6-99dd-7831c1d422a2', 0, e'Drawing maps:\n\nhttps://github.com/ajstarks/svgo\nPerhaps render svg -> imagehttps://stackoverflow.com/questions/26641273/how-to-write-a-polyline-in-golang\n\nStraight ->\nImage ->\nhttps://github.com/signintech/gopdf\n\n\nhttps://github.com/llgcode/draw2d\n\n// Import geojson\nhttps://github.com/paulmach/go.geojson\n\nhttps://github.com/kellydunn/golang-geo\n\n// Go library\nhttps://github.com/paulmach/go.geo\n\n```\npackage main\n\nimport (\n\t"github.com/jung-kurt/gofpdf"\n\t"log"\n)\n\nfunc main() {\n\tpdf := gofpdf.New("L", "mm", "A4", "")\n\tpdf.AddPage()\n\tpdf.SetFillColor(0, 120, 30)\n\tpdf.SetTextColor(0, 120, 30)\n\tpdf.SetFont("Times", "B", 16)\n\tpdf.Text(5.0, 10, "Practice Numbers")\n\tpdf.Rect(5.0, 21.0, 50.0, 20.0, "F")\n\tpdf.Rect(5.0, 42.0, 124.0, 20.0, "F")\n\tpdf.Rect(5.0, 63.0, 84.0, 20.0, "F")\n\tpdf.Rect(5.0, 84.0, 10.0, 20.0, "F")\n\terr := pdf.OutputFileAndClose("hello.pdf")\n\tlog.Fatal(err)\n}\n```\n\n// Normalize:\nfind min and max for x and y\ne.g. -33.822, -33.840, subtract to get range. = 18 divide into target 200/18 = unit\n\ntype Aus struct {\n  Features []Feature `features`\n}\n\ntype Feature struct {\n   Geometry Geo `geometry`\n}\n\ntype Geo struct {\n  Coords \n}\n\n\n\n', '', '', 1, 1496901393247, 0, 0, 0, '2e9b2422a1eb1c5a04b914362701b97e5b79c071656b27bda62026a8a48a5f0f', '', false, false, '', false, '', false, 0, 1496914798510, 1501194062625, 1501194062625, e'\x1b[0m'),
	('richard', 'gpsyn-pdf', 'txt', 5, '721acb66-2146-46e8-aa14-e6d8de1a3e80', '', '', '', '', '', 'synergia', 'c9b2b5d8-f00c-11e6-99dd-7831c1d422a2', 0, e'Drawing maps:\n\nhttps://github.com/ajstarks/svgo\nPerhaps render svg -> imagehttps://stackoverflow.com/questions/26641273/how-to-write-a-polyline-in-golang\n\nStraight ->\nImage ->\nhttps://github.com/signintech/gopdf\n\n\nhttps://github.com/llgcode/draw2d\n\n// Import geojson\nhttps://github.com/paulmach/go.geojson\n\nhttps://github.com/kellydunn/golang-geo\n\n// Go library\nhttps://github.com/paulmach/go.geo\n\n```\npackage main\n\nimport (\n\t"github.com/jung-kurt/gofpdf"\n\t"log"\n)\n\nfunc main() {\n\tpdf := gofpdf.New("L", "mm", "A4", "")\n\tpdf.AddPage()\n\tpdf.SetFillColor(0, 120, 30)\n\tpdf.SetTextColor(0, 120, 30)\n\tpdf.SetFont("Times", "B", 16)\n\tpdf.Text(5.0, 10, "Practice Numbers")\n\tpdf.Rect(5.0, 21.0, 50.0, 20.0, "F")\n\tpdf.Rect(5.0, 42.0, 124.0, 20.0, "F")\n\tpdf.Rect(5.0, 63.0, 84.0, 20.0, "F")\n\tpdf.Rect(5.0, 84.0, 10.0, 20.0, "F")\n\terr := pdf.OutputFileAndClose("hello.pdf")\n\tlog.Fatal(err)\n}\n```\n\n// Normalize:\nfind min and max for x and y\ne.g. -33.822, -33.840, subtract to get range. = 18 divide into target 200/18 = unit\n\ntype Aus struct {\n  Features []Feature `features`\n}\n\ntype Feature struct {\n   Geometry Geo `geometry`\n}\n\ntype Geo struct {\n  Coords \n}\n\n/////\nhttps://github.com/rowanhogan/australian-states\n\npackage main\n\nimport (\n\t"github.com/jung-kurt/gofpdf"\n\t"log"\n\t"github.com/paulmach/go.geojson"\n\t"io/ioutil"\n\t"path/filepath"\n\t"fmt"\n\t"time"\n)\n\nfunc main() {\n\tstart := time.Now()\n\tpdf := gofpdf.New("L", "mm", "A4", "")\n\tpdf.AddPage()\n\tpdf.SetFillColor(202, 202, 159)\n\tpdf.SetTextColor(0, 120, 30)\n\tpdf.SetFont("Times", "B", 16)\n\n\tp, _ := filepath.Abs("pdf/aus.json")\n\tjs, err := ioutil.ReadFile(p)\n\tif err != nil {\n\t\tlog.Fatal(err)\n\t}\n\taus, err := geojson.UnmarshalFeatureCollection(js)\n\tprintShape(pdf, 1, aus)\n\terr = pdf.OutputFileAndClose("hello.pdf")\n\telapsed := time.Since(start)\n\tlog.Printf("Binomial took %s", elapsed)\n\tlog.Fatal(err)\n}\n\nfunc printShape(pdf *gofpdf.Fpdf, i int, coll *geojson.FeatureCollection) {\n\tvar minx, maxx, miny, maxy float64\n\tminx = 180\n\tminy = 180\n\tloop(coll, func(x float64, y float64) {\n\t\ty += 180\n\t\tif x == 0 || y == 0 {\n\t\t\treturn\n\t\t}\n\t\tif x > maxx {\n\t\t\tmaxx = x\n\t\t}\n\t\tif x < minx {\n\t\t\tminx = x\n\t\t}\n\t\tif y > maxy {\n\t\t\tmaxy = y\n\t\t}\n\t\tif y < miny {\n\t\t\tminy = y\n\t\t}\n\t})\n\tfmt.Println(minx, maxx, miny, maxy)\n\txspan := maxx-minx\n\tyspan := maxy-miny\n\tfmt.Println(xspan, yspan)\n\txscale := 200/xspan\n\tyscale := 100/yspan\n\tvar points []gofpdf.PointType\n\tloop(coll, func(x float64, y float64) {\n\t\ty += 180\n\t\tx = (maxx-x)*xscale\n\t\ty = (maxy-y)*yscale\n\t\tpoints = append(points, gofpdf.PointType{X: x, Y: y + 50})\n\t})\n\tpdf.Polygon(points, "F")\n}\n\nfunc loop(coll *geojson.FeatureCollection, cb func(x float64, y float64)) {\n\tvar count int\n\tfor _, v := range coll.Features {\n\t\tfor _, mp := range v.Geometry.MultiPolygon {\n\t\t\tfor _, p := range mp {\n\t\t\t\tif count > 1 {\n\t\t\t\t\tcontinue\n\t\t\t\t}\n\t\t\t\tcount ++\n\t\t\t\tfor _, p2 := range p {\n\t\t\t\t\tcb(p2[0], p2[1])\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t}\n}\n\n\n\n\n', '', '', 1, 1496901393247, 0, 0, 0, 'afdfb0dcef16d4e4d6d3a75467d0c6475c5ffa0f6aab7e77b46223b0617a9db5', '', false, false, '', false, '', false, 0, 1496914852534, 1501194062625, 1501194062625, e'\x1b[0m'),
