	('richard', 'gpsynergy-vms', 'txt', 2, '7f53fd8c-12ab-4aa6-b0aa-8aa993b0acef', '', '', '', '', '', 'synergia', 'c9b2b5d8-f00c-11e6-99dd-7831c1d422a2', 0, e'\nDev app tier VM:\n\nHostname: synergiadev1.australiaeast.cloudapp.azure.com\nIP: 13.73.197.163\nIve locked down ports 80 and 443 to your whitelist IP of 210.54.37.176', '', '', 0, 0, 0, 0, 0, '4691bedfd6eaf1bbe76266711b75b1fa8500cb0b45d911b0185a59c5b83bdc5e', '', false, false, '', false, '', false, 0, 1498778884082, 1498778902714, 1498778902714, ''),
	('richard', 'gpsynergy-vms', 'txt', 3, '7f53fd8c-12ab-4aa6-b0aa-8aa993b0acef', '', '', '', '', '', 'synergia', 'c9b2b5d8-f00c-11e6-99dd-7831c1d422a2', 0, e'\n## Dev \n\n# App tier VM (MacBook pro ssh pub key)\n\nHostname: synergiadev1.australiaeast.cloudapp.azure.com\nIP: 13.73.197.163\nIve locked down ports 80 and 443 to your whitelist IP of 210.54.37.176\n\n# SQL tier\n\nServer: synergiadev1.database.windows.net\nLogin:  web_user\nPwd:  N\'W3b~U$3r\n', '', '', 1, 1498781962320, 0, 1, 0, 'daa7cc574976d84f42de1cc46a2561b21a0dfd59aab87e71abd6ea27dbdefdd4', '', false, false, '', false, '', false, 0, 1498779009796, 1498779009796, 1498781962320, e'\x1b[0m'),
	('richard', 'gpsynergy-vms', 'txt', 4, '7f53fd8c-12ab-4aa6-b0aa-8aa993b0acef', '', '', '', '', '', 'synergia', 'c9b2b5d8-f00c-11e6-99dd-7831c1d422a2', 0, e'\n## Dev \n\n# App tier VM (MacBook pro ssh pub key)\n\nHostname: synergiadev1.australiaeast.cloudapp.azure.com\nIP: 13.73.197.163\nIve locked down ports 80 and 443 to your whitelist IP of 210.54.37.176\n\n# SQL tier\n\n{\n  "user": "web_user",\n  "password": "W3b~U$3r",\n  "server": "synergiadev1.database.windows.net",\n  "database":"GPS_Synergia",\n  "options": {\n     "encrypt": true\n  }\n}', '', '', 1, 1498781962320, 0, 0, 0, '2a1fc51f60440c9bbc9fd875d65d69f2ea089833901d29a030e2b012ab981ae9', '', false, false, '', true, '', false, 0, 1498782794175, 1498782794175, 1498782794175, e'\x1b[0m'),
	('richard', 'grouppriority', 'txt', 2, 'bdea533a-1424-11e7-8c55-7831c1d422a2', '', '', '', '', '', 'synergia', 'c9b2b5d8-f00c-11e6-99dd-7831c1d422a2', 0, e'We have changed many logics for the \U0000201CGroup Preference\U0000201D column in excel sheet. We considered Re enrolment, Registrar Group Setting(limiting) and placement data for the group selection and applied the following score system. \nRe enrolment = 1\nFor Registrar Group Setting =2\nAnd Placement = 3\n   \nWe will select a group with the highest score. X in the above scenario has highest score.\nIf more than one groups have same score, we will pick first group in the alphabet order. For e.g. if total score of   A and C is 1, we will select 1 as it come first in the order.\n \nIf you need further clarification we can setup zoom meeting.\n', '', '', 0, 0, 0, 0, 0, '9f9d054c32ba2cf91239fb3e4cf7df9a9ab02c9bebe348524ca85e978c2b7ab6', '', false, false, '', true, 'cass', false, 0, 1490753407694, 1495404775059, 0, ''),
	('richard', 'jira', 'url', 1, '25c7a8d4-46a6-4ace-b49d-3a14f2e61f75', '', '', '', '', '', 'synergia', 'c9b2b5d8-f00c-11e6-99dd-7831c1d422a2', 0, '', '', '', 0, 0, 0, 0, 0, 'e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855', '', false, false, '', false, 'map[agnt:<not implemented> addr:[::1]:55648 v:v0.8.17+02cfb93 host:Richards-MacBook-Pro.local os:darwin]', false, 0, 1499399787785, 1499399800498, 1499399800498, ''),
	('richard', 'jira', 'url', 2, '25c7a8d4-46a6-4ace-b49d-3a14f2e61f75', '', '', '', '', '', 'synergia', 'c9b2b5d8-f00c-11e6-99dd-7831c1d422a2', 0, 'https://synergia.atlassian.net/', '', '', 1, 1499399888669, 0, 2, 0, 'bb477d787707e977be267a54b9580e0c1fa24f047b5c29c70bce62339925a2b3', '', false, false, '', true, '', false, 0, 1499399794160, 1499399800498, 1499399888669, e'\x1b[0m'),
	('richard', 'lumiov1', 'url', 1, '854b4bb0-ccb5-11e6-8e2a-27249dd1b81b', '', '', '', '', '', 'synergia', 'c9b2b5d8-f00c-11e6-99dd-7831c1d422a2', 0, 'http://www.lumio.com.au/about', '', '', 0, 0, 0, 0, 0, 'a822ee5ba70c1da5988a1c6ce90f391e515b1190a265c44f481af218d44252ec', '', false, false, '', true, 'cass', false, 0, 1479945600000, 1495404782004, 0, ''),
	('richard', 'mates-contract', 'txt', 2, 'a614cbd1-2930-11e7-b56f-7831c1d422a2', '', '', '', '', '', 'synergia', 'c9b2b5d8-f00c-11e6-99dd-7831c1d422a2', 0, e'Hi Richard,\n\nFollowing up on our conversation - given your estimate of $7,360 for the following items (plus $1,840 contingency), I suggest we go for:\nhourly rate at $115 per hour\na minimum payment of $5,000 regardless of how long it takes you \ni.e. if you do it in 3 days, we will still pay $5,000\nup to a maximum of $9,000 (assuming no scope changes)\nif it starts looking like it will be close to this, let us know asap\n\nItems in scope:\nUser management (16hrs)\nSchool management (8hrs)\nProvider management (8hrs)\nModule and session management (16hrs)\nDevOps (8hrs)\nQuestionnaire integration (8hrs)\n\nIf that works for you, then do you want to come in tomorrow at 11:30am to scope out the detail etc & get going?\n\nAnd just to reiterate - really happy for you to reuse the user management stuff in your own personal projects.\n\n--------------------\n\nFor the moment these items are out of scope, but I\'ll let you know on Friday if this changes (and there may be some more stuff we identify on Fri):\nData import (4hrs)\nDashboard (8hrs)\nWeekly email (16hrs)', '', '', 0, 1493067470000, 0, 0, 0, '954de129f2f26045e3179d2f78a3cd8dd4ff74faa4a3bf9e72e8f01674732109', '', false, false, '', true, 'cass', false, 0, 1493067466263, 1495404771507, 0, '');
