	('richard', 'mates-dates', 'txt', 3, '1e5bafe7-bb2d-409a-a3b8-375bacb70846', '', '', '', '', '', 'synergia', 'c9b2b5d8-f00c-11e6-99dd-7831c1d422a2', 0, e'mongodb://[username:password@]host1[:port1][,host2[:port2],...[,hostN[:portN]]][/[database][?options]]\n\nMONGO_URL=mongodb://api_user:sdfkj\u00A3\u00A3fjdf76sdfsJKJ@mongo:27017/student_survey\n\nMongo user:\ndb.createUser({user:"api_user",pwd:"sdfkj\u00A3\u00A3fjdf76sdfsJKJ", roles:[{role:"dbAdmin", db:"student_survey"}]})', '', '', 0, 0, 0, 0, 0, 'a1cb2427716c452e7d0de7234dbfa486b77a630d5ddd4c9b9805a79d2ef23818', '', false, false, '', false, '', false, 0, 1499405477508, 1499405477508, 1499405477508, ''),
	('richard', 'mates-dates', 'txt', 4, '1e5bafe7-bb2d-409a-a3b8-375bacb70846', '', '', '', '', '', 'synergia', 'c9b2b5d8-f00c-11e6-99dd-7831c1d422a2', 0, e'mongodb://[username:password@]host1[:port1][,host2[:port2],...[,hostN[:portN]]][/[database][?options]]\n\nMongo user:\ndb.createUser({user:"api_user",pwd:"sdfkj\u00A3\u00A3fjdf76sdfsJKJ", roles:[{role:"dbAdmin", db:"student_survey"}]})\n\n\nMONGO_URL=mongodb://api_user:sdfkj\u00A3\u00A3fjdf76sdfsJKJ@mongo:27017/student_survey\nNODE_ENV=production\nTOKEN_API_URL=https://mates-and-dates.synergia.nz/api/v1/module-exists/{hash}', '', '', 1, 1499644739118, 0, 1, 0, '9f22ed8eb8cd8bb20f37470ff2f87f5159d6db9abe36f7ef14876c734984af5d', '', false, false, '', true, '', false, 0, 1499405625084, 1499405625084, 1499644739118, e'\x1b[0m'),
	('richard', 'matesdates', 'txt', 5, '4ab22779-2491-11e7-b3bf-7831c1d422a2', '', '', '', '', '', 'synergia', 'c9b2b5d8-f00c-11e6-99dd-7831c1d422a2', 0, e'>> notes here\n\nProgram Management Portal\n\n\n** Super User (Same as ACC admin)\nACC Admin\n\t- Create providers\n\t- Create Schools\n\t- Create All users (except super)\n\t- Assign Schools to providers (Can assign school to different providers)\n    - Assign User to providers\n    - Can see ALL modules\n    \nProvider Manager\n\t- Create/Edit module of provider\n\t- Reassign module to provider user\n\t- Create & Edit users associated with provider\n\t- Edit provider details\n\nFacilitator (Can only work for one provider)\n\t- Create & edit modules associated with self\n\t- Can only see modules associated with self\n\t- Edit my details\n\t\nInformis / access\n\nSchools\n\t- 75 Schools\n\t- Split address\n\t- Can have many providers\n\nModules\n\t- method to list open modules\n\t- 5 Sessions (Hard coded)\n\t- then take survey\n\t- school, year, class, module, = unique code\n\t- created by facilitator (Author)\n\t\t- nest session in module\n\t- complete module (check all sessions done)\n\t- edited date\n\t  - sessions have disclosures with severity\n\t  - email notification not in scope\n\n\n- Online portal\n\t- code initially just urls (hard coded)\n\n- When creating a new user give random password\n- First time login change password\n- 8 chars 1 upper, 1 number OR symbol or length is (option greater than 15)\n- Email\n- Send email to notify\n\n// endpoints\nADMIN\nPOST /providers (create provider)\nPOST /schools (create school)\nPOST /users (create user)\nPUT /providers/:id/add-school (Add provider to school)\nPUT /users/:id (Add user to provider)\n\nMANAGER\nPUT /providers/:id\nPOST /providers/:id/modules (create module)\nGET  /providers/:id/modules\nPOST /providers/:id/users create user\nPUT /providers/:id/users update user\n\nFACILITATOR\nPOST/PUT /modules/:id\n/providers/:id/schools\n/providers/:id/schools/:id/modules/:id\n/providers/:id/users/:id\n', '', '', 0, 1492985004000, 0, 0, 0, '2a2fbbc839ded67a84a994c9b8b1663ecf78cb0754c44059830abc6d7934aec4', '', false, false, '', true, 'cass', false, 0, 1492985017566, 1495404771589, 0, ''),
	('richard', 'notes', 'txt', 5, '87de8c18-fede-46fd-a88a-c2058e2d18c2', '', '', '', '', '', 'synergia', 'c9b2b5d8-f00c-11e6-99dd-7831c1d422a2', 0, e'move out of sandbox\nhttps://docs.aws.amazon.com/ses/latest/DeveloperGuide/request-production-access.html?icmpid=docs_ses_console\n\nhttps://us-west-2.console.aws.amazon.com/ses/home?region=us-west-2#dashboard:\n\neye institute: users module (creating updating editing)\nreset password\n\nDONE put it on server\nDONE change domain back to eye-institute', '', '', 0, 0, 0, 0, 0, '403c5d34aca46f7cda153defea755dab20fe923dfd53392c93cda0011944f125', '', false, false, '', true, '', false, 0, 1496122832112, 1496122832112, 0, ''),
