	('richard', 'ops', 'url', 1, '5e09b3b2-6af6-49cc-9ccc-06a982d5c99e', '', '', '', '', '', 'synergia', 'c9b2b5d8-f00c-11e6-99dd-7831c1d422a2', 0, 'http://ops.synergia.nz:8080/', '', '', 1, 1498170205839, 0, 7, 0, '93602a04b55ea2d20971a63652fc865ed4da5e68617d54786d15e30eb1dc387a', '', false, false, '', false, 'map[host:Richards-MacBook-Pro.local os:darwin agnt:<not implemented> addr:[::1]:61657 v:v0.8.16+eedcc49]', false, 0, 1497323722155, 1497323722155, 1498170205839, e'\x1b[0m'),
