	('richard', 'ops-deployment', 'txt', 1, 'a5aa1121-29eb-49e1-a6e7-85539fe14e20', '', '', '', '', '', 'synergia', 'c9b2b5d8-f00c-11e6-99dd-7831c1d422a2', 0, '', '', '', 0, 0, 0, 0, 0, 'e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855', '', false, false, '', false, 'map[host:Richards-MacBook-Pro.local os:darwin agnt:<not implemented> addr:[::1]:54409 v:v0.8.16+eedcc49]', false, 0, 1497391665963, 1497391665963, 1497391665963, ''),
	('richard', 'ops-deployment', 'txt', 2, 'a5aa1121-29eb-49e1-a6e7-85539fe14e20', '', '', '', '', '', 'synergia', 'c9b2b5d8-f00c-11e6-99dd-7831c1d422a2', 0, e'https://docs.rancher.com/rancher/v1.2/en/cli/\n\n# Set the url that Rancher is on\n$ export RANCHER_URL=http://<server_ip>:8080\n# Set the access key, i.e. username\n$ export RANCHER_ACCESS_KEY=<accessKey_of_account_api_key>\n# Set the secret key, i.e. password\n$ export RANCHER_SECRET_KEY=<secretKey_of_account_api_key>\nexport RANCHER_ENVIRONMENT=<environment_id>\n\nrancher config\n\nhttp://ops.synergia.nz:8080/v2-beta\nhttp://ops.synergia.nz:8080/v1\n\n92C3AA58AB0FB6A3D619\nmd7qH7gh1Sw756bye4YxbFaitkG4ScNg15jYVUW8', '', '', 0, 0, 0, 0, 0, '4f1ce984b598d9a38c788957361c2557923ed4af3212a4b90f8cdedfcea2411a', '', false, false, '', false, '', false, 0, 1497391677194, 1497391677194, 1497391677194, ''),
