	('richard', 'print-div', 'js', 5, '3f9dd5af-1812-11e7-8bbf-7831c1d422a2', '', '', '', '', '', 'synergia', 'c9b2b5d8-f00c-11e6-99dd-7831c1d422a2', 0, e'\t// Should also consider media queries\n\t// Use safari emulation to check works in ie\n\n\t// HTML:\n\t//<button ng-click="vm.printDiv(\'printableArea\');">Print Div</button>\n\t\n       vm.printDiv = function(divName) {\n            var printContents = document.getElementById(divName).innerHTML;\n            var originalContents = document.body.innerHTML;\n            document.body.innerHTML = printContents;\n            window.print();\n            document.body.innerHTML = originalContents;\n        };', '', '', 1, 1491185582000, 0, 0, 0, '59e114b2e299b44160a52445f18d49d328794f4f324edce1892b72797dddd2f4', '', false, false, '', true, 'cass', false, 0, 1491185578386, 1495404773618, 0, e'\x1b[0m'),
