	('richard', 'prometheus', 'url', 1, 'ba5ce0f1-8a4b-4b4c-9938-2334786bd310', '', '', '', '', '', 'synergia', 'c9b2b5d8-f00c-11e6-99dd-7831c1d422a2', 0, 'http://dolphin.node.synergia.nz:9090/', '', '', 1, 1499971989097, 0, 1, 0, '41c2fd1e1bde25964ef9d1ac32753ce18924a721337e2ea183ac46b400658870', '', false, false, '', true, 'map[os:darwin agnt:<not implemented> addr:[::1]:62873 v:v0.8.17+02cfb93 host:Richards-MacBook-Pro.local]', false, 0, 1499971969168, 1499971969168, 1499971989097, e'\x1b[0m'),
	('richard', 'sample', 'go', 3, 'ee4de02d-249f-11e7-b3c0-7831c1d422a2', '', '', '', '', '', 'synergia', 'c9b2b5d8-f00c-11e6-99dd-7831c1d422a2', 0, e'package main\n\nimport (\n  "fmt"\n  "log"\n  "net/http"\n)\n\nfunc Log(handler http.Handler) http.Handler {\n  return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {\n    log.Printf("%s %s %s", r.RemoteAddr, r.Method, r.URL)\n    handler.ServeHTTP(w, r)\n  })\n}\n\nfunc handler(w http.ResponseWriter, r *http.Request) {\n  fmt.Fprintf(w, "Hello %s!", r.URL.Path)\n}\n\nfunc main() {\n  http.HandleFunc("/", handler)\n  http.ListenAndServe(":8002", Log(http.DefaultServeMux))\n}', '', '', 1, 1492565966000, 0, 0, 0, '858cec599a21660c4c6088e95b31939cc69dbcc6143ca07352423f2f57b8524b', '', false, false, '', true, 'cass', false, 0, 1492565658282, 1495404771776, 0, e'\x1b[0m'),
