	('symbols', 'cassseed', 'txt', 1, '859f1100-ccb5-11e6-8e2a-27249dd1b81b', '', '', '', '', '', '', '', 0, e'CREATE KEYSPACE "kwk"   \nWITH REPLICATION = {\'class\' : \'NetworkTopologyStrategy\', \'DC1\' : 1 };  \n    \ndrop KEYSPACE "kwk";  \n  \n- CREATE KEYSPACE "kwk"  \n--  WITH REPLICATION = {\'class\' : \'SimpleStrategy\', \'replication_factor\' : 1 };  \n  \ndrop table aliases;  \n    \ncreate table "aliases" (  \n username varchar,  \n "key" varchar,  \n runtime varchar,  \n created timestamp,  \n updated timestamp,  \n primary key (("username"), "updated", "key", "runtime")  \n )  \n with CLUSTERING order by (updated desc, "key" asc, "runtime" asc);  \n   \n  \nINSERT INTO kwk.aliases  \n(username, "key", runtime, updated, created)  \nVALUES(\'richard\', \'hello\', \'nodejs\', toTimestamp(now()), toTimestamp(now()));  \n  \nINSERT INTO kwk.aliases  \n(username, "key", runtime, updated, created)  \nVALUES(\'richard\', \'hello\', \'java\', toTimestamp(now()), toTimestamp(now()));', '', '', 0, 0, 0, 0, 0, '654bbff284658d4f03b96e81a954a3f19689089eb241fe4a49a990e76e0fd161', '', true, false, '', true, 'cass', false, 0, 1480464000000, 1495404771049, 0, ''),
