CREATE TABLE api_use (
	username STRING(50) NOT NULL,
	use_time TIMESTAMP NULL,
	CONSTRAINT "primary" PRIMARY KEY (username ASC),
	FAMILY "primary" (username, use_time)
);

CREATE TABLE pouches (
	username STRING(50) NOT NULL,
	name STRING(100) NOT NULL,
	id STRING(36) NULL,
	type INT NULL DEFAULT 0:::INT,
	encrypt BOOL NULL DEFAULT false,
	make_private BOOL NULL DEFAULT false,
	shared_with STRING(3000) NULL,
	last_use INT NULL DEFAULT 0:::INT,
	clone_count INT NULL DEFAULT 0:::INT,
	green_count INT NULL DEFAULT 0:::INT,
	red_count INT NULL DEFAULT 0:::INT,
	run_count INT NULL DEFAULT 0:::INT,
	snip_count INT NULL DEFAULT 0:::INT,
	view_count INT NULL DEFAULT 0:::INT,
	delete_time INT NOT NULL DEFAULT 0:::INT,
	deleted BOOL NOT NULL DEFAULT false,
	created INT NULL DEFAULT 0:::INT,
	updated INT NULL DEFAULT 0:::INT,
	CONSTRAINT "primary" PRIMARY KEY (username ASC, name ASC, deleted ASC, delete_time ASC),
	FAMILY "primary" (username, name, id, type, encrypt, make_private, shared_with, last_use, clone_count, green_count, red_count, run_count, snip_count, view_count, delete_time, deleted, created, updated)
);

CREATE TABLE snip_use (
	username STRING(50) NOT NULL,
	use_time TIMESTAMP NOT NULL DEFAULT current_timestamp(),
	snip_id STRING(36) NOT NULL,
	api_version STRING(20) NULL,
	client STRING(300) NULL,
	deps STRING(300) NULL,
	encrypted BOOL NULL DEFAULT false,
	ext STRING(12) NULL,
	host STRING(300) NULL,
	name STRING(50) NULL,
	pouch STRING(50) NULL,
	pouch_id STRING(36) NULL,
	princ_uname STRING(50) NULL,
	private BOOL NULL DEFAULT false,
	use_status INT NULL DEFAULT 0:::INT,
	use_type INT NULL DEFAULT 0:::INT,
	CONSTRAINT "primary" PRIMARY KEY (username ASC, use_time ASC, snip_id ASC),
	FAMILY "primary" (username, use_time, snip_id, api_version, client, deps, encrypted, ext, host, name, pouch, pouch_id, princ_uname, private, use_status, use_type)
);

CREATE TABLE snippets (
	username STRING(50) NOT NULL,
	name STRING(100) NOT NULL,
	ext STRING(12) NOT NULL,
	version INT NOT NULL,
	id STRING(36) NOT NULL,
	apps STRING NULL DEFAULT '':::STRING,
	attribution STRING(300) NULL,
	cloned_from_uri STRING(300) NULL,
	dependencies STRING NULL DEFAULT '':::STRING,
	description STRING(300) NULL,
	pouch STRING(50) NOT NULL,
	pouch_id STRING(36) NULL,
	role INT NULL DEFAULT 0:::INT,
	content STRING(12000) NULL,
	supported_on STRING(300) NULL DEFAULT '':::STRING,
	tags STRING(300) NULL DEFAULT '':::STRING,
	run_status INT NULL DEFAULT 0:::INT,
	run_status_time INT NULL DEFAULT 0:::INT,
	clone_count INT NULL DEFAULT 0:::INT,
	run_count INT NULL DEFAULT 0:::INT,
	view_count INT NULL DEFAULT 0:::INT,
	checksum STRING(300) NULL,
	signature STRING(300) NULL,
	public BOOL NULL DEFAULT false,
	encrypted BOOL NULL DEFAULT false,
	encrypted_algo STRING(300) NULL,
	latest BOOL NULL DEFAULT true,
	metadata STRING(1000) NULL,
	deleted BOOL NOT NULL DEFAULT false,
	delete_time INT NOT NULL DEFAULT 0:::INT,
	created INT NULL DEFAULT 0:::INT,
	updated INT NULL DEFAULT 0:::INT,
	touched INT NULL DEFAULT 0:::INT,
	preview STRING(300) NULL,
	CONSTRAINT "primary" PRIMARY KEY (username ASC, pouch ASC, name ASC, ext ASC, version ASC, deleted ASC, delete_time ASC),
	FAMILY "primary" (username, name, ext, version, id, apps, attribution, cloned_from_uri, dependencies, description, pouch, pouch_id, role, content, supported_on, tags, run_status, run_status_time, clone_count, run_count, view_count, checksum, signature, public, encrypted, encrypted_algo, latest, metadata, deleted, delete_time, created, updated, touched, preview)
);













